insert into occupations (code, title, description, job_zone, median_wage, growth_pct, source_ids) values
  ('11-1021.00', 'General and Operations Managers', 'Plan, direct, or coordinate the operations of public or private sector organizations, overseeing multiple departments or locations. Duties and responsibilities include formulating policies, managing daily operations, and planning the use of materials and human resources, but are too diverse and general in nature to be classified in any one functional area of management or administration, such as personnel, purchasing, or administrative services. Usually manage through subordinate supervisors. Excludes First-Line Supervisors.', 4, 105770, 5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-1031.00', 'Legislators', 'Develop, introduce, or enact laws and statutes at the local, tribal, state, or federal level. Includes only workers in elected positions.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-2011.00', 'Advertising and Promotions Managers', 'Plan, direct, or coordinate advertising policies and programs or produce collateral materials, such as posters, contests, coupons, or giveaways, to create extra interest in the purchase of a product or service for a department, an entire organization, or on an account basis.', 4, 133660, -3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-2021.00', 'Marketing Managers', 'Plan, direct, or coordinate marketing policies and programs, such as determining the demand for products and services offered by a firm and its competitors, and identify potential customers. Develop pricing strategies with the goal of maximizing the firm''s profits or share of the market while ensuring the firm''s customers are satisfied. Oversee product development or monitor trends that indicate the need for new products and services.', 4, 166790, 6.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-2022.00', 'Sales Managers', 'Plan, direct, or coordinate the actual distribution or movement of a product or service to the customer. Coordinate sales distribution by establishing sales territories, quotas, and goals and establish training programs for sales representatives. Analyze sales statistics gathered by staff to determine sales potential and inventory requirements and monitor the preferences of customers.', 4, 148270, 4.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-2032.00', 'Public Relations Managers', 'Plan, direct, or coordinate activities designed to create or maintain a favorable public image or raise issue awareness for their organization or client.', 4, 146910, 5.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-2033.00', 'Fundraising Managers', 'Plan, direct, or coordinate activities to solicit and maintain funds for special projects or nonprofit organizations.', 4, 125470, 5.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3012.00', 'Administrative Services Managers', 'Plan, direct, or coordinate one or more administrative services of an organization, such as records and information management, mail distribution, and other office support services.', 3, 114130, 5.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3013.00', 'Facilities Managers', 'Plan, direct, or coordinate operations and functionalities of facilities and buildings. May include surrounding grounds or multiple facilities of an organization''s campus.', 3, 106660, 4.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3013.01', 'Security Managers', 'Direct an organization''s security functions, including physical security and safety of employees and facilities.', 4, 106660, 4.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3021.00', 'Computer and Information Systems Managers', 'Plan, direct, or coordinate activities in such fields as electronic data processing, information systems, systems analysis, and computer programming.', 4, 175140, 15.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3031.00', 'Financial Managers', 'Plan, direct, or coordinate accounting, investing, banking, insurance, securities, and other financial activities of a branch, office, or department of an establishment.', 4, 166570, 9.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3031.01', 'Treasurers and Controllers', 'Direct financial activities, such as planning, procurement, and investments for all or part of an organization.', 4, 166570, 9.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3031.03', 'Investment Fund Managers', 'Plan, direct, or coordinate investment strategy or operations for a large pool of liquid assets supplied by institutional investors or individual investors.', 5, 166570, 9.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3051.00', 'Industrial Production Managers', 'Plan, direct, or coordinate the work activities and resources necessary for manufacturing products in accordance with cost, quality, and quantity specifications.', 4, 126060, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3051.01', 'Quality Control Systems Managers', 'Plan, direct, or coordinate quality assurance programs. Formulate quality control policies and control quality of laboratory and production efforts.', 4, 126060, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3051.02', 'Geothermal Production Managers', 'Manage operations at geothermal power generation facilities. Maintain and monitor geothermal plant equipment for efficient and safe plant operations.', 3, 126060, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3051.03', 'Biofuels Production Managers', 'Manage biofuels production and plant operations. Collect and process information on plant production and performance, diagnose problems, and design corrective procedures.', 4, 126060, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3051.04', 'Biomass Power Plant Managers', 'Manage operations at biomass power generation facilities. Direct work activities at plant, including supervision of operations and maintenance staff.', 4, 126060, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3051.06', 'Hydroelectric Production Managers', 'Manage operations at hydroelectric power generation facilities. Maintain and monitor hydroelectric plant equipment for efficient and safe plant operations.', 3, 126060, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3061.00', 'Purchasing Managers', 'Plan, direct, or coordinate the activities of buyers, purchasing officers, and related workers involved in purchasing materials, products, and services. Includes wholesale or retail trade merchandising managers and procurement managers.', 4, 148080, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3071.00', 'Transportation, Storage, and Distribution Managers', 'Plan, direct, or coordinate transportation, storage, or distribution activities in accordance with organizational policies and applicable government laws or regulations. Includes logistics managers.', 4, 107230, 6.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3071.04', 'Supply Chain Managers', 'Direct or coordinate production, purchasing, warehousing, distribution, or financial forecasting services or activities to limit costs and improve accuracy, customer service, or safety. Examine existing procedures or opportunities for streamlining activities to meet product distribution needs. Direct the movement, storage, or processing of inventory.', 4, 107230, 6.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3111.00', 'Compensation and Benefits Managers', 'Plan, direct, or coordinate compensation and benefits activities of an organization.', 4, 149230, 1.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3121.00', 'Human Resources Managers', 'Plan, direct, or coordinate human resources activities and staff of an organization.', 4, 149280, 5.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3131.00', 'Training and Development Managers', 'Plan, direct, or coordinate the training and development activities and staff of an organization.', 4, 133000, 6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9013.00', 'Farmers, Ranchers, and Other Agricultural Managers', 'Plan, direct, or coordinate the management or operation of farms, ranches, greenhouses, aquacultural operations, nurseries, timber tracts, or other agricultural establishments. May hire, train, and supervise farm workers or contract for services to carry out the day-to-day activities of the managed operation. May engage in or supervise planting, cultivating, harvesting, and financial and marketing activities.', 4, 89900, -3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9021.00', 'Construction Managers', 'Plan, direct, or coordinate, usually through subordinate supervisory personnel, activities concerned with the construction and maintenance of structures, facilities, and systems. Participate in the conceptual development of a construction project and oversee its organization, scheduling, budgeting, and implementation. Includes managers in specialized construction fields, such as carpentry or plumbing.', 4, 114990, 9.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9031.00', 'Education and Childcare Administrators, Preschool and Daycare', 'Plan, direct, or coordinate academic or nonacademic activities of preschools or childcare centers and programs, including before- and after-school care.', 4, 59300, -3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9032.00', 'Education Administrators, Kindergarten through Secondary', 'Plan, direct, or coordinate the academic, administrative, or auxiliary activities of kindergarten, elementary, or secondary schools.', 5, 105870, -0.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9033.00', 'Education Administrators, Postsecondary', 'Plan, direct, or coordinate student instruction, administration, and services, as well as other research and educational activities, at postsecondary institutions, including universities, colleges, and junior and community colleges.', 5, 104590, 1.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9041.00', 'Architectural and Engineering Managers', 'Plan, direct, or coordinate activities in such fields as architecture and engineering or research and development in these fields.', 5, 171270, 5.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9041.01', 'Biofuels/Biodiesel Technology and Product Development Managers', 'Define, plan, or execute biofuels/biodiesel research programs that evaluate alternative feedstock and process technologies with near-term commercial potential.', 4, 171270, 5.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9072.00', 'Entertainment and Recreation Managers, Except Gambling', 'Plan, direct, or coordinate entertainment and recreational activities and operations of a recreational facility, including cruise ships and parks.', 4, 79520, 6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9081.00', 'Lodging Managers', 'Plan, direct, or coordinate activities of an organization or department that provides lodging and other accommodations.', 4, 69250, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9111.00', 'Medical and Health Services Managers', 'Plan, direct, or coordinate medical and health services in hospitals, clinics, managed care organizations, public health agencies, or similar organizations.', 4, 123860, 24.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9121.00', 'Natural Sciences Managers', 'Plan, direct, or coordinate activities in such fields as life sciences, physical sciences, mathematics, statistics, and research and development in these fields.', 5, 167220, 8.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9121.01', 'Clinical Research Coordinators', 'Plan, direct, or coordinate clinical research projects. Direct the activities of workers engaged in clinical research projects to ensure compliance with protocols and overall clinical objectives. May evaluate and analyze clinical data.', 4, 167220, 8.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9121.02', 'Water Resource Specialists', 'Design or implement programs and strategies related to water resource issues such as supply, quality, and regulatory compliance issues.', 4, 167220, 8.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9141.00', 'Property, Real Estate, and Community Association Managers', 'Plan, direct, or coordinate the selling, buying, leasing, or governance activities of commercial, industrial, or residential real estate properties. Includes managers of homeowner and condominium associations, rented or leased housing units, buildings, or land (including rights-of-way).', 4, 69990, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9151.00', 'Social and Community Service Managers', 'Plan, direct, or coordinate the activities of a social service program or community outreach organization. Oversee the program or organization''s budget and policies regarding participant involvement, program requirements, and benefits. Work may involve directing social workers, counselors, or probation officers.', 4, 80390, 7.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9161.00', 'Emergency Management Directors', 'Plan and direct disaster response or crisis management activities, provide disaster preparedness training, and prepare emergency plans and procedures for natural (e.g., hurricanes, floods, earthquakes), wartime, or technological (e.g., nuclear power plant emergencies or hazardous materials spills) disasters or hostage situations.', 4, 93330, 3.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9171.00', 'Funeral Home Managers', 'Plan, direct, or coordinate the services or resources of funeral homes. Includes activities such as determining prices for services or merchandise and managing the facilities of funeral homes.', 3, 78790, 4.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9179.01', 'Fitness and Wellness Coordinators', 'Manage or coordinate fitness and wellness programs and services. Manage and train staff of wellness specialists, health educators, or fitness instructors.', 4, 69770, 6.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9179.02', 'Spa Managers', 'Plan, direct, or coordinate activities of a spa facility. Coordinate programs, schedule and direct staff, and oversee financial activities.', 3, 69770, 6.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9199.01', 'Regulatory Affairs Managers', 'Plan, direct, or coordinate production activities of an organization to ensure compliance with regulations and standard operating procedures.', 4, 141900, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9199.02', 'Compliance Managers', 'Plan, direct, or coordinate activities of an organization to ensure compliance with ethical or regulatory standards.', 4, 141900, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9199.08', 'Loss Prevention Managers', 'Plan and direct policies, procedures, or systems to prevent the loss of assets. Determine risk exposure or potential liability, and develop risk control measures.', 4, 141900, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9199.09', 'Wind Energy Operations Managers', 'Manage wind field operations, including personnel, maintenance activities, financial activities, and planning.', 3, 141900, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9199.10', 'Wind Energy Development Managers', 'Lead or manage the development and evaluation of potential wind energy business opportunities, including environmental studies, permitting, and proposals. May also manage construction of projects.', 4, 141900, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9199.11', 'Brownfield Redevelopment Specialists and Site Managers', 'Plan and direct cleanup and redevelopment of contaminated properties for reuse. Does not include properties sufficiently contaminated to qualify as Superfund sites.', 4, 141900, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1011.00', 'Agents and Business Managers of Artists, Performers, and Athletes', 'Represent and promote artists, performers, and athletes in dealings with current or prospective employers. May handle contract negotiation and other business matters for clients.', 4, 82890, 9.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1021.00', 'Buyers and Purchasing Agents, Farm Products', 'Purchase farm products either for further processing or resale. Includes tree farm contractors, grain brokers and market operators, grain buyers, and tobacco buyers. May negotiate contracts.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1022.00', 'Wholesale and Retail Buyers, Except Farm Products', 'Buy merchandise or commodities, other than farm products, for resale to consumers at the wholesale or retail level, including both durable and nondurable goods. Analyze past buying trends, sales records, price, and quality of merchandise to determine value and yield. Select, order, and authorize payment for merchandise according to contractual agreements. May conduct meetings with sales personnel and introduce new products. May negotiate contracts. Includes assistant wholesale and retail buyers of nonfarm products.', 3, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1023.00', 'Purchasing Agents, Except Wholesale, Retail, and Farm Products', 'Purchase machinery, equipment, tools, parts, supplies, or services necessary for the operation of an establishment. Purchase raw or semifinished materials for manufacturing. May negotiate contracts.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1031.00', 'Claims Adjusters, Examiners, and Investigators', 'Review settled claims to determine that payments and settlements are made in accordance with company practices and procedures. Confer with legal counsel on claims requiring litigation. May also settle insurance claims.', 4, 78000, -5.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1032.00', 'Insurance Appraisers, Auto Damage', 'Appraise automobile or other vehicle damage to determine repair costs for insurance claim settlement. Prepare insurance forms to indicate repair cost or cost estimates and recommendations. May seek agreement with automotive repair shop on repair costs.', 3, 78240, -8.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1041.00', 'Compliance Officers', 'Examine, evaluate, and investigate eligibility for or conformity with laws and regulations governing contract compliance of licenses and permits, and perform other compliance and enforcement inspection and analysis activities not classified elsewhere.', 4, 80730, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1041.01', 'Environmental Compliance Inspectors', 'Inspect and investigate sources of pollution to protect the public and environment and ensure conformance with Federal, State, and local regulations and ordinances.', 4, 80730, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1041.03', 'Equal Opportunity Representatives and Officers', 'Monitor and evaluate compliance with equal opportunity laws, guidelines, and policies to ensure that employment practices and contracting arrangements give equal opportunity without regard to race, religion, color, national origin, sex, age, or disability.', 4, 80730, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1041.04', 'Government Property Inspectors and Investigators', 'Investigate or inspect government property to ensure compliance with contract agreements and government regulations.', 3, 80730, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1041.06', 'Coroners', 'Direct activities such as autopsies, pathological and toxicological analyses, and inquests relating to the investigation of deaths occurring within a legal jurisdiction to determine cause of death or to fix responsibility for accidental, violent, or unexplained deaths.', 3, 80730, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1041.07', 'Regulatory Affairs Specialists', 'Coordinate and document internal regulatory processes, such as internal audits, inspections, license renewals, or registrations. May compile and prepare materials for submission to regulatory agencies.', 4, 80730, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1041.08', 'Customs Brokers', 'Prepare customs documentation and ensure that shipments meet all applicable laws to facilitate the import and export of goods. Determine and track duties and taxes payable and process payments on behalf of client. Sign documents under a power of attorney. Represent clients in meetings with customs officials and apply for duty refunds and tariff reclassifications. Coordinate transportation and storage of imported goods.', 3, 80730, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1051.00', 'Cost Estimators', 'Prepare cost estimates for product manufacturing, construction projects, or services to aid management in bidding on or determining price of product or service. May specialize according to particular service performed or type of product manufactured.', 4, 78740, -3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1071.00', 'Human Resources Specialists', 'Recruit, screen, interview, or place individuals within an organization. May perform other activities in multiple human resources areas.', 4, 75940, 6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1075.00', 'Labor Relations Specialists', 'Resolve disputes between workers and managers, negotiate collective bargaining agreements, or coordinate grievance procedures to handle employee complaints.', 4, 95420, 2.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1081.00', 'Logisticians', 'Analyze and coordinate the ongoing logistical functions of a firm or organization. Responsible for the entire life cycle of a product, including acquisition, distribution, internal allocation, delivery, and final disposal of resources.', 4, 82320, 17.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1081.01', 'Logistics Engineers', 'Design or analyze operational solutions for projects such as transportation optimization, network modeling, process and methods analysis, cost containment, capacity enhancement, routing and shipment optimization, or information management.', 4, 82320, 17.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1081.02', 'Logistics Analysts', 'Analyze product delivery or supply chain processes to identify or recommend changes. May manage route activity including invoicing, electronic bills, and shipment tracing.', 4, 82320, 17.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1082.00', 'Project Management Specialists', 'Analyze and coordinate the schedule, timeline, procurement, staffing, and budget of a product or service on a per project basis. Lead and guide the work of technical staff. May serve as a point of contact for the client or customer.', 4, 102320, 6.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1111.00', 'Management Analysts', 'Conduct organizational studies and evaluations, design systems and procedures, conduct work simplification and measurement studies, and prepare operations and procedures manuals to assist management in operating more efficiently and effectively. Includes program analysts and management consultants.', 4, 101860, 10.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1121.00', 'Meeting, Convention, and Event Planners', 'Coordinate activities of staff, convention personnel, or clients to make arrangements for group meetings, events, or conventions.', 4, 61160, 5.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1131.00', 'Fundraisers', 'Organize activities to raise funds or otherwise solicit and gather monetary donations or other gifts for an organization. May design and produce promotional materials. May also raise awareness of the organization''s work, goals, and financial needs.', 4, 72550, 5.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1141.00', 'Compensation, Benefits, and Job Analysis Specialists', 'Conduct programs of compensation and benefits and job analysis for employer. May specialize in specific areas, such as position classification and pension programs.', 4, 78210, 6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1151.00', 'Training and Development Specialists', 'Design or conduct work-related training and development programs to improve individual skills or organizational performance. May analyze organizational training needs or evaluate training effectiveness.', 4, 69280, 10.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1161.00', 'Market Research Analysts and Marketing Specialists', 'Research conditions in local, regional, national, or online markets. Gather information to determine potential sales of a product or service, or plan a marketing or advertising campaign. May gather information on competitors, prices, sales, and methods of marketing and distribution. May employ search marketing tactics, analyze web metrics, and develop recommendations to increase search engine ranking and visibility to target markets.', 4, 78760, 7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1161.01', 'Search Marketing Strategists', 'Employ search marketing tactics to increase visibility and engagement with content, products, or services in Internet-enabled devices or interfaces. Examine search query behaviors on general or specialty search engines or other Internet-based content. Analyze research, data, or technology to understand user intent and measure outcomes for ongoing optimization.', 4, 78760, 7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1199.04', 'Business Continuity Planners', 'Develop, maintain, or implement business continuity and disaster recovery strategies and solutions, including risk assessments, business impact analyses, strategy selection, and documentation of business continuity and disaster recovery procedures. Plan, conduct, and debrief regular mock-disaster exercises to test the adequacy of existing plans and strategies, updating procedures and plans regularly. Act as a coordinator for continuity efforts after a disruption event.', 4, 83050, 3.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1199.05', 'Sustainability Specialists', 'Address organizational sustainability issues, such as waste stream management, green building practices, and green procurement plans.', 4, 83050, 3.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1199.06', 'Online Merchants', 'Conduct retail activities of businesses operating exclusively online. May perform duties such as preparing business strategies, buying merchandise, managing inventory, implementing marketing activities, fulfilling and shipping online orders, and balancing financial records.', 4, 83050, 3.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1199.07', 'Security Management Specialists', 'Conduct security assessments for organizations, and design security systems and processes. May specialize in areas such as physical security or the safety of employees and facilities.', 4, 83050, 3.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2011.00', 'Accountants and Auditors', 'Examine, analyze, and interpret accounting records to prepare financial statements, give advice, or audit and evaluate statements prepared by others. Install or advise on systems of recording costs or other financial and budgetary data.', 4, 83680, 5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2022.00', 'Appraisers of Personal and Business Property', 'Appraise and estimate the fair value of tangible personal or business property, such as jewelry, art, antiques, collectibles, and equipment. May also appraise land.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2023.00', 'Appraisers and Assessors of Real Estate', 'Appraise real estate, exclusively, and estimate its fair value. May assess taxes in accordance with prescribed schedules.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2031.00', 'Budget Analysts', 'Examine budget estimates for completeness, accuracy, and conformance with procedures and regulations. Analyze budgeting and accounting reports.', 4, 91640, 1.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2041.00', 'Credit Analysts', 'Analyze credit data and financial statements of individuals or firms to determine the degree of risk involved in extending credit or lending money. Prepare reports with credit information for use in decisionmaking.', 4, 83510, -4.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2051.00', 'Financial and Investment Analysts', 'Conduct quantitative analyses of information involving investment programs or financial data of public or private institutions, including valuation of businesses.', 4, 102740, 7.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2052.00', 'Personal Financial Advisors', 'Advise clients on financial plans using knowledge of tax and investment strategies, securities, insurance, pension plans, and real estate. Duties include assessing clients'' assets, liabilities, cash flow, insurance coverage, tax status, and financial objectives. May also buy and sell financial assets for clients.', 4, 105070, 1.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2053.00', 'Insurance Underwriters', 'Review individual applications for insurance to evaluate degree of risk involved and determine acceptance of applications.', 4, 81370, -3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2054.00', 'Financial Risk Specialists', 'Analyze and measure exposure to credit and market risk threatening the assets, earning capacity, or economic state of an organization. May make recommendations to limit risk.', 4, 117330, 7.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2061.00', 'Financial Examiners', 'Enforce or ensure compliance with laws and regulations governing financial and securities institutions and financial and real estate transactions. May examine, verify, or authenticate records.', 4, 94160, 9.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2071.00', 'Credit Counselors', 'Advise and educate individuals or organizations on acquiring and managing debt. May provide guidance in determining the best type of loan and explain loan requirements or restrictions. May help develop debt management plans or student financial aid packages. May advise on credit issues, or provide budget, mortgage, bankruptcy, or student financial aid counseling.', 4, 52230, 3.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2072.00', 'Loan Officers', 'Evaluate, authorize, or recommend approval of commercial, real estate, or credit loans. Advise borrowers on financial status and payment methods. Includes mortgage loan officers and agents, collection analysts, loan servicing officers, loan underwriters, and payday loan officers.', 4, 76690, 1.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2081.00', 'Tax Examiners and Collectors, and Revenue Agents', 'Determine tax liability or collect taxes from individuals or business firms according to prescribed laws and regulations.', 3, 62370, -1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2082.00', 'Tax Preparers', 'Prepare tax returns for individuals or small businesses.', 3, 54920, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2099.01', 'Financial Quantitative Analysts', 'Develop quantitative techniques to inform securities investing, equities investing, pricing, or valuation of financial instruments. Develop mathematical or statistical models for risk management, asset optimization, pricing, or relative value analysis.', 5, 81100, 4.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2099.04', 'Fraud Examiners, Investigators and Analysts', 'Obtain evidence, take statements, produce reports, and testify to findings regarding resolution of fraud allegations. May coordinate fraud detection and prevention activities.', 4, 81100, 4.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1211.00', 'Computer Systems Analysts', 'Analyze science, engineering, business, and other data processing problems to develop and implement solutions to complex applications problems, system administration issues, or network concerns. Perform systems management and integration functions, improve existing computer systems, and review computer system capabilities, workflow, and schedule limitations. May analyze or recommend commercially available software.', 4, 105850, 7.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1211.01', 'Health Informatics Specialists', 'Apply knowledge of nursing and informatics to assist in the design, development, and ongoing modification of computerized health care systems. May educate staff and assist in problem solving to promote the implementation of the health care system.', 5, 105850, 7.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1212.00', 'Information Security Analysts', 'Plan, implement, upgrade, or monitor security measures for the protection of computer networks and information. Assess system vulnerabilities for security risks and propose and implement risk mitigation strategies. May ensure appropriate security controls are in place that will safeguard digital files and vital electronic infrastructure. May respond to computer security breaches and viruses.', 4, 129180, 21, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1221.00', 'Computer and Information Research Scientists', 'Conduct research into fundamental computer and information science as theorists, designers, or inventors. Develop solutions to problems in the field of computer hardware and software.', 5, 140300, 21.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1231.00', 'Computer Network Support Specialists', 'Analyze, test, troubleshoot, and evaluate existing network systems, such as local area networks (LAN), wide area networks (WAN), cloud networks, servers, and other data communications networks. Perform network maintenance to ensure networks operate correctly with minimal interruption.', 4, 76220, 1.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1232.00', 'Computer User Support Specialists', 'Provide technical assistance to computer users. Answer questions or resolve computer problems for clients in person, via telephone, or electronically. May provide assistance concerning the use of computer hardware and software, including printing, installation, word processing, electronic mail, and operating systems.', 3, 61860, -3.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1241.00', 'Computer Network Architects', 'Design and implement computer and information networks, such as local area networks (LAN), wide area networks (WAN), intranets, extranets, and other data communications networks. Perform network modeling, analysis, and planning, including analysis of capacity needs for network infrastructures. May also design network and computer security measures. May research and recommend network and data communications hardware and software.', 4, 134050, 7.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1241.01', 'Telecommunications Engineering Specialists', 'Design or configure wired, wireless, and satellite communications systems for voice, video, and data services. Supervise installation, service, and maintenance.', 3, 134050, 7.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1242.00', 'Database Administrators', 'Administer, test, and implement computer databases, applying knowledge of database management systems. Coordinate changes to computer databases. Identify, investigate, and resolve database performance issues, database capacity, and database scalability. May plan, coordinate, and implement security measures to safeguard computer databases.', 4, 104620, -0.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1243.00', 'Database Architects', 'Design strategies for enterprise databases, data warehouse systems, and multidimensional networks. Set standards for database operations, programming, query processes, and security. Model, design, and construct large relational databases or data warehouses. Create and optimize data models for warehouse infrastructure and workflow. Integrate new systems with existing warehouse structure and refine system performance and functionality.', 4, 139500, 9.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1243.01', 'Data Warehousing Specialists', 'Design, model, or implement corporate data warehousing activities. Program and configure warehouses of database information and provide support to warehouse users.', 4, 139500, 9.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1244.00', 'Network and Computer Systems Administrators', 'Install, configure, and maintain an organization''s local area network (LAN), wide area network (WAN), data communications network, operating systems, and physical and virtual servers. Perform system monitoring and verify the integrity and availability of hardware, network, and server resources and systems. Review system and application logs and verify completion of scheduled jobs, including system backups. Analyze network and server resource consumption and control user access. Install and upgrade software and maintain software licenses. May assist in network modeling, analysis, planning, and coordination between network and data communications hardware and software.', 3, 99130, -4.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1251.00', 'Computer Programmers', 'Create, modify, and test the code and scripts that allow computer applications to run. Work from specifications drawn up by software and web developers or other individuals. May develop and write computer programs to store, locate, and retrieve specific documents, data, and information.', 4, 100390, -7.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1252.00', 'Software Developers', 'Research, design, and develop computer and network software or specialized utility programs. Analyze user needs and develop software solutions, applying principles and techniques of computer science, engineering, and mathematical analysis. Update software or enhance existing software capabilities. May work with computer hardware engineers to integrate hardware and software systems, and develop specifications and performance requirements. May maintain databases within an application area, working individually or coordinating database development as part of a team.', 4, 135980, 10.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1253.00', 'Software Quality Assurance Analysts and Testers', 'Develop and execute software tests to identify software problems and their causes. Test system modifications to prepare for implementation. Document software and application defects using a bug tracking system and report defects to software or web developers. Create and maintain databases of known defects. May participate in software design reviews to provide input on functional requirements, operational characteristics, product designs, and schedules.', 4, 104300, 5.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1254.00', 'Web Developers', 'Develop and implement websites, web applications, application databases, and interactive web interfaces. Evaluate code to ensure that it is properly structured, meets industry standards, and is compatible with browsers and devices. Optimize website performance, scalability, and server-side code and processes. May develop website infrastructure and integrate websites with other computer applications.', 3, 92650, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1255.00', 'Web and Digital Interface Designers', 'Design digital user interfaces or websites. Develop and test layouts, interfaces, functionality, and navigation menus to ensure compatibility and usability across browsers or devices. May use web framework applications as well as client-side code and processes. May evaluate web design following web and accessibility standards, and may analyze web use metrics and optimize websites for marketability and search engine ranking. May design and test interfaces that facilitate the human-computer interaction and maximize the usability of digital devices, websites, and software with a focus on aesthetics and design. May create graphics used in websites and manage website content and links.', 4, 104000, 6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1255.01', 'Video Game Designers', 'Design core features of video games. Specify innovative game and role-play mechanics, story lines, and character biographies. Create and maintain design documentation. Guide and collaborate with production staff to produce games as designed.', 4, 104000, 6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.01', 'Web Administrators', 'Manage web environment design, deployment, development and maintenance activities. Perform testing and quality assurance of web sites and web applications.', 4, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.02', 'Geographic Information Systems Technologists and Technicians', 'Assist scientists or related professionals in building, maintaining, modifying, or using geographic information systems (GIS) databases. May also perform some custom application development or provide user support.', 4, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.03', 'Document Management Specialists', 'Implement and administer enterprise-wide document management systems and related procedures that allow organizations to capture, store, retrieve, share, and destroy electronic records and documents.', 4, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.04', 'Penetration Testers', 'Evaluate network system security by conducting simulated internal and external cyberattacks using adversary tools and techniques. Attempt to breach and exploit critical systems and gain access to sensitive information to assess system security.', 4, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.05', 'Information Security Engineers', 'Develop and oversee the implementation of information security procedures and policies. Build, maintain and upgrade security technology, such as firewalls, for the safe use of computer networks and the transmission and retrieval of information. Design and implement appropriate security controls to identify vulnerabilities and protect digital files and electronic infrastructures. Monitor and respond to computer security breaches, viruses, and intrusions, and perform forensic investigation. May oversee the assessment of information security systems.', 4, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.06', 'Digital Forensics Analysts', 'Conduct investigations on computer-based crimes establishing documentary or physical evidence, such as digital media and logs associated with cyber intrusion incidents. Analyze digital evidence and investigate computer security incidents to derive information in support of system and network vulnerability mitigation. Preserve and present computer-related evidence in support of criminal, fraud, counterintelligence, or law enforcement investigations.', 4, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.07', 'Blockchain Engineers', 'Maintain and support distributed and decentralized blockchain-based networks or block-chain applications such as cryptocurrency exchange, payment processing, document sharing, and digital voting. Design and deploy secure block-chain design patterns and solutions over geographically distributed networks using advanced technologies. May assist with infrastructure setup and testing for application transparency and security.', 4, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.08', 'Computer Systems Engineers/Architects', 'Design and develop solutions to complex applications problems, system administration issues, or network concerns. Perform systems management and integration functions.', 3, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.09', 'Information Technology Project Managers', 'Plan, initiate, and manage information technology (IT) projects. Lead and guide the work of technical staff. Serve as liaison between business and technical aspects of projects. Plan project stages and assess business implications for each stage. Monitor progress to assure deadlines, standards, and cost targets are met.', 4, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2011.00', 'Actuaries', 'Analyze statistical data, such as mortality, accident, sickness, disability, and retirement rates and construct probability tables to forecast risk and liability for payment of future benefits. May ascertain insurance rates required and cash reserves necessary to ensure payment of future benefits.', 4, 130000, 9.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2021.00', 'Mathematicians', 'Conduct research in fundamental mathematics or in application of mathematical techniques to science, management, and other fields. Solve problems in various fields using mathematical methods.', 5, 126710, 0.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2031.00', 'Operations Research Analysts', 'Formulate and apply mathematical modeling and other optimizing methods to develop and interpret information that assists management with decisionmaking, policy formulation, or other managerial functions. May collect and analyze data and develop decision support software, services, or products. May develop and supply optimal time, cost, or logistics networks for program evaluation, review, or implementation.', 5, 88940, 11.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2041.00', 'Statisticians', 'Develop or apply mathematical or statistical theory and methods to collect, organize, interpret, and summarize numerical data to provide usable information. May specialize in fields such as biostatistics, agricultural statistics, business statistics, or economic statistics. Includes mathematical and survey statisticians.', 5, 105650, 11, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2041.01', 'Biostatisticians', 'Develop and apply biostatistical theory and methods to the study of life sciences.', 5, 105650, 11, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2051.00', 'Data Scientists', 'Develop and implement a set of techniques or analytics applications to transform raw data into meaningful information using data-oriented programming languages and visualization software. Apply data mining, data modeling, natural language processing, and machine learning to extract and analyze information from large structured and unstructured datasets. Visualize, interpret, and report data findings. May create dynamic data reports.', 4, 120230, 34.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2051.01', 'Business Intelligence Analysts', 'Produce financial and market intelligence by querying data repositories and generating periodic reports. Devise methods for identifying data patterns and trends in available information sources.', 4, 120230, 34.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2051.02', 'Clinical Data Managers', 'Apply knowledge of health care and database management to analyze clinical data, and to identify and report trends.', 4, 120230, 34.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2099.01', 'Bioinformatics Technicians', 'Apply principles and methods of bioinformatics to assist scientists in areas such as pharmaceuticals, medical technology, biotechnology, computational biology, proteomics, computer information science, biology and medical informatics. Apply bioinformatics tools to visualize, analyze, manipulate or interpret molecular data. May build and maintain databases for processing and analyzing genomic or other biological information.', 4, 81490, 7.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-1011.00', 'Architects, Except Landscape and Naval', 'Plan and design structures, such as private residences, office buildings, theaters, factories, and other structural property.', 5, 99280, 4.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-1012.00', 'Landscape Architects', 'Plan and design land areas for projects such as parks and other recreational facilities, airports, highways, hospitals, schools, land subdivisions, and commercial, industrial, and residential sites.', 4, 79870, 4.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-1021.00', 'Cartographers and Photogrammetrists', 'Research, study, and prepare maps and other spatial data in digital or graphic form for one or more purposes, such as legal, social, political, educational, and design purposes. May work with Geographic Information Systems (GIS). May design and evaluate algorithms, data structures, and user interfaces for GIS and mapping systems. May collect, analyze, and interpret geographic information provided by geodetic surveys, aerial photographs, and satellite data.', 4, 81390, 7.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-1022.00', 'Surveyors', 'Make exact measurements and determine property boundaries. Provide data relevant to the shape, contour, gravitation, location, elevation, or dimension of land or land features on or near the earth''s surface for engineering, mapmaking, mining, land evaluation, construction, and other purposes.', 4, 75440, 5.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-1022.01', 'Geodetic Surveyors', 'Measure large areas of the Earth''s surface using satellite observations, global navigation satellite systems (GNSS), light detection and ranging (LIDAR), or related sources.', 4, 75440, 5.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2011.00', 'Aerospace Engineers', 'Perform engineering duties in designing, constructing, and testing aircraft, missiles, and spacecraft. May conduct basic and applied research to evaluate adaptability of materials and equipment to aircraft design and manufacture. May recommend improvements in testing equipment and techniques.', 4, 134960, 8.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2021.00', 'Agricultural Engineers', 'Apply knowledge of engineering technology and biological science to agricultural problems concerned with power and machinery, electrification, structures, soil and water conservation, and processing of agricultural products.', 4, 98590, 6.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2031.00', 'Bioengineers and Biomedical Engineers', 'Apply knowledge of engineering, biology, chemistry, computer science, and biomechanical principles to the design, development, and evaluation of biological, agricultural, and health systems and products, such as artificial organs, prostheses, instrumentation, medical information systems, and health management and care delivery systems.', 4, 109370, 7.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2041.00', 'Chemical Engineers', 'Design chemical plant equipment and devise processes for manufacturing chemicals and products, such as gasoline, synthetic rubber, plastics, detergents, cement, paper, and pulp, by applying principles and technology of chemistry, physics, and engineering.', 4, 125040, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2051.00', 'Civil Engineers', 'Perform engineering duties in planning, designing, and overseeing construction and maintenance of building structures and facilities, such as roads, railroads, airports, bridges, harbors, channels, dams, irrigation projects, pipelines, power plants, and water and sewage systems.', 4, 100840, 6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2051.01', 'Transportation Engineers', 'Develop plans for surface transportation projects, according to established engineering standards and state or federal construction policy. Prepare designs, specifications, or estimates for transportation facilities. Plan modifications of existing streets, highways, or freeways to improve traffic flow.', 4, 100840, 6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2051.02', 'Water/Wastewater Engineers', 'Design or oversee projects involving provision of potable water, disposal of wastewater and sewage, or prevention of flood-related damage. Prepare environmental documentation for water resources, regulatory program compliance, data management and analysis, and field work. Perform hydraulic modeling and pipeline design.', 4, 100840, 6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2061.00', 'Computer Hardware Engineers', 'Research, design, develop, or test computer or computer-related equipment for commercial, industrial, military, or scientific use. May supervise the manufacturing and installation of computer or computer-related equipment and components.', 4, 161740, 9.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2071.00', 'Electrical Engineers', 'Research, design, develop, test, or supervise the manufacturing and installation of electrical equipment, components, or systems for commercial, industrial, military, or scientific use.', 4, 120630, 9.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2072.00', 'Electronics Engineers, Except Computer', 'Research, design, develop, or test electronic components and systems for commercial, industrial, military, or scientific use employing knowledge of electronic theory and materials properties. Design electronic circuits and components for use in fields such as telecommunications, aerospace guidance and propulsion control, acoustics, or instruments and controls.', 4, 130220, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2072.01', 'Radio Frequency Identification Device Specialists', 'Design and implement radio frequency identification device (RFID) systems used to track shipments or goods.', 4, 130220, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2081.00', 'Environmental Engineers', 'Research, design, plan, or perform engineering duties in the prevention, control, and remediation of environmental hazards using various engineering disciplines. Work may include waste treatment, site remediation, or pollution control technology.', 4, 107110, 6.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2111.00', 'Health and Safety Engineers, Except Mining Safety Engineers and Inspectors', 'Promote worksite or product safety by applying knowledge of industrial processes, mechanics, chemistry, psychology, and industrial health and safety laws. Includes industrial product safety engineers.', 4, 115160, 5.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2111.02', 'Fire-Prevention and Protection Engineers', 'Research causes of fires, determine fire protection methods, and design or recommend materials or equipment such as structural components or fire-detection equipment to assist organizations in safeguarding life and property against fire, explosion, and related hazards.', 4, 115160, 5.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2112.00', 'Industrial Engineers', 'Design, develop, test, and evaluate integrated systems for managing industrial production processes, including human work factors, quality control, inventory control, logistics and material flow, cost analysis, and production coordination.', 4, 102440, 12.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2112.01', 'Human Factors Engineers and Ergonomists', 'Design objects, facilities, and environments to optimize human well-being and overall system performance, applying theory, principles, and data regarding the relationship between humans and respective technology. Investigate and analyze characteristics of human behavior and performance as it relates to the use of technology.', 5, 102440, 12.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2112.02', 'Validation Engineers', 'Design or plan protocols for equipment or processes to produce products meeting internal and external purity, safety, and quality requirements.', 4, 102440, 12.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2112.03', 'Manufacturing Engineers', 'Design, integrate, or improve manufacturing systems or related processes. May work with commercial or industrial designers to refine product designs to increase producibility and decrease costs.', 4, 102440, 12.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2121.00', 'Marine Engineers and Naval Architects', 'Design, develop, and evaluate the operation of marine vessels, ship machinery, and related equipment, such as power supply and propulsion systems.', 4, 112230, 6.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2131.00', 'Materials Engineers', 'Evaluate materials and develop machinery and processes to manufacture materials for use in products that must meet specialized design and performance specifications. Develop new uses for known materials. Includes those engineers working with composite materials or specializing in one type of material, such as graphite, metal and metal alloys, ceramics and glass, plastics and polymers, and naturally occurring materials. Includes metallurgists and metallurgical engineers, ceramic engineers, and welding engineers.', 4, 112860, 7.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2141.00', 'Mechanical Engineers', 'Perform engineering duties in planning and designing tools, engines, machines, and other mechanically functioning equipment. Oversee installation, operation, maintenance, and repair of equipment such as centralized heat, gas, water, and steam systems.', 4, 104110, 11.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2141.01', 'Fuel Cell Engineers', 'Design, evaluate, modify, or construct fuel cell components or systems for transportation, stationary, or portable applications.', 4, 104110, 11.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2141.02', 'Automotive Engineers', 'Develop new or improved designs for vehicle structural members, engines, transmissions, or other vehicle systems, using computer-assisted design technology. Direct building, modification, or testing of vehicle or components.', 4, 104110, 11.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2151.00', 'Mining and Geological Engineers, Including Mining Safety Engineers', 'Conduct subsurface surveys to identify the characteristics of potential land or mining development sites. May specify the ground support systems, processes, and equipment for safe, economical, and environmentally sound extraction or underground construction activities. May inspect areas for unsafe geological conditions, equipment, and working conditions. May design, implement, and coordinate mine safety programs.', 4, 106220, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2161.00', 'Nuclear Engineers', 'Conduct research on nuclear engineering projects or apply principles and theory of nuclear science to problems concerned with release, control, and use of nuclear energy and nuclear waste disposal.', 4, 133970, 0.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2171.00', 'Petroleum Engineers', 'Devise methods to improve oil and gas extraction and production and determine the need for new or modified tool designs. Oversee drilling and offer technical advice.', 4, 144910, 2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2199.03', 'Energy Engineers, Except Wind and Solar', 'Design, develop, or evaluate energy-related projects or programs to reduce energy costs or improve energy efficiency during the designing, building, or remodeling stages of construction. May specialize in electrical systems; heating, ventilation, and air-conditioning (HVAC) systems; green buildings; lighting; air quality; or energy procurement.', 4, 122930, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2199.05', 'Mechatronics Engineers', 'Research, design, develop, or test automation, intelligent systems, smart devices, or industrial systems control.', 4, 122930, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2199.06', 'Microsystems Engineers', 'Research, design, develop, or test microelectromechanical systems (MEMS) devices.', 5, 122930, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2199.07', 'Photonics Engineers', 'Design technologies specializing in light information or light energy, such as laser or fiber optics technology.', 4, 122930, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2199.08', 'Robotics Engineers', 'Research, design, develop, or test robotic applications.', 4, 122930, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2199.09', 'Nanosystems Engineers', 'Design, develop, or supervise the production of materials, devices, or systems of unique molecular or macromolecular composition, applying principles of nanoscale physics and electrical, chemical, or biological engineering.', 5, 122930, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2199.10', 'Wind Energy Engineers', 'Design underground or overhead wind farm collector systems and prepare and develop site specifications.', 4, 122930, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2199.11', 'Solar Energy Systems Engineers', 'Perform site-specific engineering analysis or evaluation of energy efficiency and solar projects involving residential, commercial, or industrial customers. Design solar domestic hot water and space heating systems for new and existing structures, applying knowledge of structural energy requirements, local climates, solar technology, and thermodynamics.', 4, 122930, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3011.00', 'Architectural and Civil Drafters', 'Prepare detailed drawings of architectural and structural features of buildings or drawings and topographical relief maps used in civil engineering projects, such as highways, bridges, and public works. Use knowledge of building materials, engineering practices, and mathematics to complete drawings.', 3, 66150, 5.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3012.00', 'Electrical and Electronics Drafters', 'Prepare wiring diagrams, circuit board assembly diagrams, and layout drawings used for the manufacture, installation, or repair of electrical equipment.', 3, 76870, -3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3013.00', 'Mechanical Drafters', 'Prepare detailed working diagrams of machinery and mechanical devices, including dimensions, fastening methods, and other engineering information.', 3, 71550, -6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3021.00', 'Aerospace Engineering and Operations Technologists and Technicians', 'Operate, install, adjust, and maintain integrated computer/communications systems, consoles, simulators, and other data acquisition, test, and measurement instruments and equipment, which are used to launch, track, position, and evaluate air and space vehicles. May record and interpret test data.', 3, 82890, 11.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3022.00', 'Civil Engineering Technologists and Technicians', 'Apply theory and principles of civil engineering in planning, designing, and overseeing construction and maintenance of structures and facilities under the direction of engineering staff or physical scientists.', 3, 64950, 3.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3023.00', 'Electrical and Electronic Engineering Technologists and Technicians', 'Apply electrical and electronic theory and related knowledge, usually under the direction of engineering staff, to design, build, repair, adjust, and modify electrical components, circuitry, controls, and machinery for subsequent evaluation and use by engineering staff in making engineering design decisions.', 3, 78190, 2.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3024.00', 'Electro-Mechanical and Mechatronics Technologists and Technicians', 'Operate, test, maintain, or adjust unmanned, automated, servomechanical, or electromechanical equipment. May operate unmanned submarines, aircraft, or other equipment to observe or record visual information at sites such as oil rigs, crop fields, buildings, or for similar infrastructure, deep ocean exploration, or hazardous waste removal. May assist engineers in testing and designing robotics equipment.', 3, 73900, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3024.01', 'Robotics Technicians', 'Build, install, test, or maintain robotic equipment or related automated production systems.', 3, 73900, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3025.00', 'Environmental Engineering Technologists and Technicians', 'Apply theory and principles of environmental engineering to modify, test, and operate equipment and devices used in the prevention, control, and remediation of environmental problems, including waste treatment and site remediation, under the direction of engineering staff or scientists. May assist in the development of environmental remediation devices.', 4, 59920, 3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3026.00', 'Industrial Engineering Technologists and Technicians', 'Apply engineering theory and principles to problems of industrial layout or manufacturing production, usually under the direction of engineering staff. May perform time and motion studies on worker operations in a variety of industries for purposes such as establishing standard production rates or improving efficiency.', 3, 66120, 3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3026.01', 'Nanotechnology Engineering Technologists and Technicians', 'Implement production processes and operate commercial-scale production equipment to produce, test, or modify materials, devices, or systems of unique molecular or macromolecular composition. Operate advanced microscopy equipment to manipulate nanoscale objects. Work under the supervision of nanoengineering staff.', 4, 66120, 3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3027.00', 'Mechanical Engineering Technologists and Technicians', 'Apply theory and principles of mechanical engineering to modify, develop, test, or adjust machinery and equipment under direction of engineering staff or physical scientists.', 3, 74510, 1.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3027.01', 'Automotive Engineering Technicians', 'Assist engineers in determining the practicality of proposed product design changes and plan and carry out tests on experimental test devices or equipment for performance, durability, or efficiency.', 3, 74510, 1.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3028.00', 'Calibration Technologists and Technicians', 'Execute or adapt procedures and techniques for calibrating measurement devices, by applying knowledge of measurement science, mathematics, physics, chemistry, and electronics, sometimes under the direction of engineering staff. Determine measurement standard suitability for calibrating measurement devices. May perform preventive maintenance on equipment. May perform corrective actions to address identified calibration problems.', 3, 67820, 4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3029.08', 'Photonics Technicians', 'Build, install, test, or maintain optical or fiber optic equipment, such as lasers, lenses, or mirrors, using spectrometers, interferometers, or related equipment.', 3, 78350, 2.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3031.00', 'Surveying and Mapping Technicians', 'Perform surveying and mapping duties, usually under the direction of an engineer, surveyor, cartographer, or photogrammetrist, to obtain data used for construction, mapmaking, boundary location, mining, or other purposes. May calculate mapmaking information and create maps from source data, such as surveying notes, aerial photography, satellite data, or other maps to show topographical features, political boundaries, and other features. May verify accuracy and completeness of maps.', 3, 54240, 5.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1011.00', 'Animal Scientists', 'Conduct research in the genetics, nutrition, reproduction, growth, and development of domestic farm animals.', 5, 68940, 5.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1012.00', 'Food Scientists and Technologists', 'Use chemistry, microbiology, engineering, and other sciences to study the principles underlying the processing and deterioration of foods; analyze food content to determine levels of vitamins, fat, sugar, and protein; discover new food sources; research ways to make processed foods safe, palatable, and healthful; and apply food science knowledge to determine best ways to process, package, preserve, store, and distribute food.', 4, 88720, 6.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1013.00', 'Soil and Plant Scientists', 'Conduct research in breeding, physiology, production, yield, and management of crops and agricultural plants or trees, shrubs, and nursery stock, their growth in soils, and control of pests; or study the chemical, physical, biological, and mineralogical composition of soils as they relate to plant or crop growth. May classify and map soils and investigate effects of alternative practices on soil and crop productivity.', 5, 78850, 6.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1021.00', 'Biochemists and Biophysicists', 'Study the chemical composition or physical principles of living cells and organisms, their electrical and mechanical energy, and related phenomena. May conduct research to further understanding of the complex chemical combinations and reactions involved in metabolism, reproduction, growth, and heredity. May determine the effects of foods, drugs, serums, hormones, and other substances on tissues and vital processes of living organisms.', 5, 127410, 12.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1022.00', 'Microbiologists', 'Investigate the growth, structure, development, and other characteristics of microscopic organisms, such as bacteria, algae, or fungi. Includes medical microbiologists who study the relationship between organisms and disease or the effects of antibiotics on microorganisms.', 4, 87990, 6.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1023.00', 'Zoologists and Wildlife Biologists', 'Study the origins, behavior, diseases, genetics, and life processes of animals and wildlife. May specialize in wildlife research and management. May collect and analyze biological data to determine the environmental effects of present and potential use of land and water habitats.', 4, 76780, 3.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1029.01', 'Bioinformatics Scientists', 'Conduct research using bioinformatics theory and methods in areas such as pharmaceuticals, medical technology, biotechnology, computational biology, proteomics, computer information science, biology and medical informatics. May design databases and develop algorithms for processing and analyzing genomic information, or other biological information.', 5, 98920, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1029.02', 'Molecular and Cellular Biologists', 'Research and study cellular molecules and organelles to understand cell function and organization.', 5, 98920, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1029.03', 'Geneticists', 'Research and study the inheritance of traits at the molecular, organism or population level. May evaluate or treat patients with genetic disorders.', 5, 98920, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1029.04', 'Biologists', 'Research or study basic principles of plant and animal life, such as origin, relationship, development, anatomy, and functions.', 5, 98920, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1031.00', 'Conservation Scientists', 'Manage, improve, and protect natural resources to maximize their use without damaging the environment. May conduct soil surveys and develop plans to eliminate soil erosion or to protect rangelands. May instruct farmers, agricultural production managers, or ranchers in best ways to use crop rotation, contour plowing, or terracing to conserve soil and water; in the number and kind of livestock and forage plants best suited to particular ranges; and in range and farm improvements, such as fencing and reservoirs for stock watering.', 4, 73010, 5.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1031.02', 'Range Managers', 'Research or study range land management practices to provide sustained production of forage, livestock, and wildlife.', 4, 73010, 5.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1031.03', 'Park Naturalists', 'Plan, develop, and conduct programs to inform public of historical, natural, and scientific features of national, state, or local park.', 4, 73010, 5.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1032.00', 'Foresters', 'Manage public and private forested lands for economic, recreational, and conservation purposes. May inventory the type, amount, and location of standing timber, appraise the timber''s worth, negotiate the purchase, and draw up contracts for procurement. May determine how to conserve wildlife habitats, creek beds, water quality, and soil stability, and how best to comply with environmental regulations. May devise plans for planting and growing new trees, monitor trees for healthy growth, and determine optimal harvesting schedules.', 4, 76400, 2.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1041.00', 'Epidemiologists', 'Investigate and describe the determinants and distribution of disease, disability, or health outcomes. May develop the means for prevention and control.', 5, 87220, 18.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1042.00', 'Medical Scientists, Except Epidemiologists', 'Conduct research dealing with the understanding of human diseases and the improvement of human health. Engage in clinical investigation, research and development, or other related activities.', 5, 103410, 12.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2011.00', 'Astronomers', 'Observe, research, and interpret astronomical phenomena to increase basic knowledge or apply such information to practical problems.', 5, 128820, 7.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2012.00', 'Physicists', 'Conduct research into physical phenomena, develop theories on the basis of observation and experiments, and devise methods to apply physical laws and theories.', 5, 172250, 7.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2021.00', 'Atmospheric and Space Scientists', 'Investigate atmospheric phenomena and interpret meteorological data, gathered by surface and air stations, satellites, and radar to prepare reports and forecasts for public and other uses. Includes weather analysts and forecasters whose functions require the detailed knowledge of meteorology.', 4, 99070, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2031.00', 'Chemists', 'Conduct qualitative and quantitative chemical analyses or experiments in laboratories for quality or process control or to develop new products or knowledge.', 4, 91240, 6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2032.00', 'Materials Scientists', 'Research and study the structures and chemical properties of various natural and synthetic or composite materials, including metals, alloys, rubber, ceramics, semiconductors, polymers, and glass. Determine ways to strengthen or combine materials or develop new materials with new or specific properties for use in a variety of products and applications. Includes glass scientists, ceramic scientists, metallurgical scientists, and polymer scientists.', 4, 117790, 8.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2041.00', 'Environmental Scientists and Specialists, Including Health', 'Conduct research or perform investigation for the purpose of identifying, abating, or eliminating sources of pollutants or hazards that affect either the environment or public health. Using knowledge of various scientific disciplines, may collect, synthesize, study, report, and recommend action based on data derived from measurements or observations of air, food, soil, water, and other sources.', 4, 82220, 6.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2041.01', 'Climate Change Policy Analysts', 'Research and analyze policy developments related to climate change. Make climate-related recommendations for actions such as legislation, awareness campaigns, or fundraising approaches.', 5, 82220, 6.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2041.02', 'Environmental Restoration Planners', 'Collaborate with field and biology staff to oversee the implementation of restoration projects and to develop new products. Process and synthesize complex scientific data into practical strategies for restoration, monitoring or management.', 5, 82220, 6.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2041.03', 'Industrial Ecologists', 'Apply principles and processes of natural ecosystems to develop models for efficient industrial systems. Use knowledge from the physical and social sciences to maximize effective use of natural resources in the production and use of goods and services. Examine societal issues and their relationship with both technical systems and the environment.', 5, 82220, 6.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2042.00', 'Geoscientists, Except Hydrologists and Geographers', 'Study the composition, structure, and other physical aspects of the Earth. May use geological, physics, and mathematics knowledge in exploration for oil, gas, minerals, or underground water; or in waste disposal, land reclamation, or other environmental problems. May study the Earth''s internal composition, atmospheres, and oceans, and its magnetic, electrical, and gravitational forces. Includes mineralogists, paleontologists, stratigraphers, geodesists, and seismologists.', 4, 101920, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2043.00', 'Hydrologists', 'Research the distribution, circulation, and physical properties of underground and surface waters; and study the form and intensity of precipitation and its rate of infiltration into the soil, movement through the earth, and return to the ocean and atmosphere.', 4, 96600, 1.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-2099.01', 'Remote Sensing Scientists and Technologists', 'Apply remote sensing principles and methods to analyze data and solve problems in areas such as natural resource management, urban planning, or homeland security. May develop new sensor systems, analytical techniques, or new applications for existing systems.', 4, 122570, 2.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3011.00', 'Economists', 'Conduct research, prepare reports, or formulate plans to address economic problems related to the production and distribution of goods and services or monetary and fiscal policy. May collect and process economic and statistical data using sampling techniques and econometric methods.', 5, 124720, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3011.01', 'Environmental Economists', 'Conduct economic analysis related to environmental protection and use of the natural environment, such as water, air, land, and renewable energy resources. Evaluate and quantify benefits, costs, incentives, and impacts of alternative options using economic principles and statistical techniques.', 5, 124720, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3022.00', 'Survey Researchers', 'Plan, develop, or conduct surveys. May analyze and interpret the meaning of survey data, determine survey objectives, or suggest or test question wording. Includes social scientists who primarily design questionnaires or supervise survey teams.', 5, 69460, -4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3032.00', 'Industrial-Organizational Psychologists', 'Apply principles of psychology to human resources, administration, management, sales, and marketing problems. Activities may include policy planning; employee testing and selection, training, and development; and organizational development and analysis. May work with management to organize the work setting to improve worker productivity.', 5, 193950, 6.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3033.00', 'Clinical and Counseling Psychologists', 'Assess, diagnose, and treat mental and emotional disorders of individuals through observation, interview, and psychological tests. Help individuals with distress or maladjustment understand their problems through their knowledge of case history, interviews with patients, and theory. Provide individual or group counseling services to assist individuals in achieving more effective personal, social, educational, and vocational development and adjustment. May design behavior modification programs and consult with medical personnel regarding the best treatment for patients.', 5, 100580, 11.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3034.00', 'School Psychologists', 'Diagnose and implement individual or schoolwide interventions or strategies to address educational, behavioral, or developmental issues that adversely impact educational functioning in a school. May address student learning and behavioral problems and counsel students or families. May design and implement performance plans, and evaluate performance. May consult with other school-based personnel.', 5, 95990, 0.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3039.02', 'Neuropsychologists', 'Apply theories and principles of neuropsychology to evaluate and diagnose disorders of higher cerebral functioning, often in research and medical settings. Study the human brain and the effect of physiological states on human cognition and behavior. May formulate and administer programs of treatment.', 5, 110840, 2.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3039.03', 'Clinical Neuropsychologists', 'Assess and diagnose patients with neurobehavioral problems related to acquired or developmental disorders of the nervous system, such as neurodegenerative disorders, traumatic brain injury, seizure disorders, and learning disabilities. Recommend treatment after diagnosis, such as therapy, medication, or surgery. Assist with evaluation before and after neurosurgical procedures, such as deep brain stimulation.', 5, 110840, 2.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3041.00', 'Sociologists', 'Study human society and social behavior by examining the groups and social institutions that people form, as well as various social, religious, political, and business organizations. May study the behavior and interaction of groups, trace their origin and growth, and analyze the influence of group activities on individual members.', 5, 106030, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3051.00', 'Urban and Regional Planners', 'Develop comprehensive plans and programs for use of land and physical facilities of jurisdictions, such as towns, cities, counties, and metropolitan areas.', 5, 89320, 3.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3091.00', 'Anthropologists and Archeologists', 'Study the origin, development, and behavior of human beings. May study the way of life, language, or physical characteristics of people in various parts of the world. May engage in systematic recovery and examination of material evidence, such as tools or pottery remaining from past human cultures, in order to determine the history, customs, and living habits of earlier civilizations.', 5, 70770, 6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3092.00', 'Geographers', 'Study the nature and use of areas of the Earth''s surface, relating and interpreting interactions of physical and cultural phenomena. Conduct research on physical aspects of a region, including land forms, climates, soils, plants, and animals, and conduct research on the spatial implications of human activities within a given area, including social characteristics, economic activities, and political organization, as well as researching interdependence between regions at scales ranging from local to global.', 4, 102040, -2.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3093.00', 'Historians', 'Research, analyze, record, and interpret the past as recorded in sources, such as government and institutional records, newspapers and other periodicals, photographs, interviews, films, electronic media, and unpublished manuscripts, such as personal diaries and letters.', 5, 76750, 3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3094.00', 'Political Scientists', 'Study the origin, development, and operation of political systems. May study topics, such as public opinion, political decisionmaking, and ideology. May analyze the structure and operation of governments, as well as various political entities. May conduct public opinion surveys, analyze election results, or analyze public documents.', 5, 142080, -2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-3099.01', 'Transportation Planners', 'Prepare studies for proposed transportation projects. Gather, compile, and analyze data. Study the use and operation of transportation systems. Develop transportation models or simulations.', 4, 101110, -0.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4012.00', 'Agricultural Technicians', 'Work with agricultural scientists in plant, fiber, and animal research, or assist with animal breeding and nutrition. Set up or maintain laboratory equipment and collect samples from crops or animals. Prepare specimens or record data to assist scientists in biology or related life science experiments. Conduct tests and experiments to improve yield and quality of crops or to increase the resistance of plants and animals to disease or insects.', 3, 49630, 5.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4012.01', 'Precision Agriculture Technicians', 'Apply geospatial technologies, including geographic information systems (GIS) and Global Positioning System (GPS), to agricultural production or management activities, such as pest scouting, site-specific pesticide application, yield mapping, or variable-rate irrigation. May use computers to develop or analyze maps or remote sensing images to compare physical topography with data on soils, fertilizer, pests, or weather.', 3, 49630, 5.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4013.00', 'Food Science Technicians', 'Work with food scientists or technologists to perform standardized qualitative and quantitative tests to determine physical or chemical properties of food or beverage products. Includes technicians who assist in research and development of production technology, quality control, packaging, processing, and use of foods.', 3, 52130, 4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4021.00', 'Biological Technicians', 'Assist biological and medical scientists. Set up, operate, and maintain laboratory instruments and equipment, monitor experiments, collect data and samples, make observations, and calculate and record results. May analyze organic substances, such as blood, food, and drugs.', 4, 57510, 7.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4031.00', 'Chemical Technicians', 'Conduct chemical and physical laboratory tests to assist scientists in making qualitative and quantitative analyses of solids, liquids, and gaseous materials for research and development of new products or processes, quality control, maintenance of environmental standards, and other work involving experimental, theoretical, or practical application of chemistry and related sciences.', 3, 60390, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4042.00', 'Environmental Science and Protection Technicians, Including Health', 'Perform laboratory and field tests to monitor the environment and investigate sources of pollution, including those that affect health, under the direction of an environmental scientist, engineer, or other specialist. May collect samples of gases, soil, water, and other materials for testing.', 4, 55090, 6.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4043.00', 'Geological Technicians, Except Hydrologic Technicians', 'Assist scientists or engineers in the use of electronic, sonic, or nuclear measuring instruments in laboratory, exploration, and production activities to obtain data indicating resources such as metallic ore, minerals, gas, coal, or petroleum. Analyze mud and drill cuttings. Chart pressure, temperature, and other characteristics of wells or bore holes.', 4, 53350, 3.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4044.00', 'Hydrologic Technicians', 'Collect and organize data concerning the distribution and circulation of ground and surface water, and data on its physical, chemical, and biological properties. Measure and report on flow rates and ground water levels, maintain field equipment, collect water samples, install and collect sampling equipment, and process samples for shipment to testing laboratories. May collect data on behalf of hydrologists, engineers, developers, government agencies, or agriculture.', 3, 64790, -1.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4051.00', 'Nuclear Technicians', 'Assist nuclear physicists, nuclear engineers, or other scientists in laboratory, power generation, or electricity production activities. May operate, maintain, or provide quality control for nuclear testing and research equipment. May monitor radiation.', 3, 110240, 1.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4051.02', 'Nuclear Monitoring Technicians', 'Collect and test samples to monitor results of nuclear experiments and contamination of humans, facilities, and environment.', 3, 110240, 1.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4061.00', 'Social Science Research Assistants', 'Assist social scientists in laboratory, survey, and other social science research. May help prepare findings for publication and assist in laboratory analysis, quality control, or data management.', 4, 61990, 5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4071.00', 'Forest and Conservation Technicians', 'Provide technical assistance regarding the conservation of soil, water, forests, or related natural resources. May compile data pertaining to size, content, condition, and other characteristics of forest tracts under the direction of foresters, or train and lead forest workers in forest propagation and fire prevention and suppression. May assist conservation scientists in managing, improving, and protecting rangelands and wildlife habitats.', 3, 54560, -2.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4092.00', 'Forensic Science Technicians', 'Collect, identify, classify, and analyze physical evidence related to criminal investigations. Perform tests on weapons or substances, such as fiber, hair, and tissue to determine significance to investigation. May testify as expert witnesses on evidence or crime laboratory techniques. May serve as specialists in area of expertise, such as ballistics, fingerprinting, handwriting, or biochemistry.', 3, 72060, 13.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4099.01', 'Quality Control Analysts', 'Conduct tests to determine quality of raw materials, bulk intermediate and finished products. May conduct stability sample tests.', 3, 62280, 4.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-4099.03', 'Remote Sensing Technicians', 'Apply remote sensing technologies to assist scientists in areas such as natural resources, urban planning, or homeland security. May prepare flight plans or sensor configurations for flight trips.', 4, 62280, 4.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-5011.00', 'Occupational Health and Safety Specialists', 'Review, evaluate, and analyze work environments and design programs and procedures to control, eliminate, and prevent disease or injury caused by chemical, physical, and biological agents or ergonomic factors. May conduct inspections and enforce adherence to laws and regulations governing the health and safety of individuals. May be employed in the public or private sector.', 4, 90150, 18.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-5012.00', 'Occupational Health and Safety Technicians', 'Collect data on work environments for analysis by occupational health and safety specialists. Implement and conduct evaluation of programs designed to limit chemical, physical, biological, and ergonomic risks to workers.', 3, 61560, 19.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1011.00', 'Substance Abuse and Behavioral Disorder Counselors', 'Counsel and advise individuals with alcohol, tobacco, drug, or other problems, such as gambling and eating disorders. May counsel individuals, families, or groups or engage in prevention programs.', 5, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1012.00', 'Educational, Guidance, and Career Counselors and Advisors', 'Advise and assist students and provide educational and vocational guidance services.', 5, 64330, 2.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1013.00', 'Marriage and Family Therapists', 'Diagnose and treat mental and emotional disorders, whether cognitive, affective, or behavioral, within the context of marriage and family systems. Apply psychotherapeutic and family systems theories and techniques in the delivery of services to individuals, couples, and families for the purpose of treating such diagnosed nervous and mental disorders.', 5, 66940, 13.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1014.00', 'Mental Health Counselors', 'Counsel and advise individuals and groups to promote optimum mental and emotional health, with an emphasis on prevention. May help individuals deal with a broad range of mental health issues, such as those associated with addictions and substance abuse; family, parenting, and marital problems; stress management; self-esteem; or aging.', 5, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1015.00', 'Rehabilitation Counselors', 'Counsel individuals to maximize the independence and employability of persons coping with personal, social, and vocational difficulties that result from birth defects, illness, disease, accidents, aging, or the stress of daily life. Coordinate activities for residents of care and treatment facilities. Assess client needs and design and implement rehabilitation programs that may include personal and vocational counseling, training, and job placement.', 5, 46850, 2.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1021.00', 'Child, Family, and School Social Workers', 'Provide social services and assistance to improve the social and psychological functioning of children and their families and to maximize the family well-being and the academic functioning of children. May assist parents, arrange adoptions, and find foster homes for abandoned or abused children. In schools, they address such problems as teenage pregnancy, misbehavior, and truancy. May also advise teachers.', 4, 59550, 4.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1022.00', 'Healthcare Social Workers', 'Provide individuals, families, and groups with the psychosocial support needed to cope with chronic, acute, or terminal illnesses. Services include advising family caregivers. Provide patients with information and counseling, and make referrals for other services. May also provide case and care management or interventions designed to promote health, prevent disease, and address barriers to access to healthcare.', 5, 67880, 8.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1023.00', 'Mental Health and Substance Abuse Social Workers', 'Assess and treat individuals with mental, emotional, or substance abuse problems, including abuse of alcohol, tobacco, and/or other drugs. Activities may include individual and group therapy, crisis intervention, case management, client advocacy, prevention, and education.', 5, 60280, 10.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1091.00', 'Health Education Specialists', 'Provide and manage health education programs that help individuals, families, and their communities maximize and maintain healthy lifestyles. Use data to identify community needs prior to planning, implementing, monitoring, and evaluating programs designed to encourage healthy lifestyles, policies, and environments. May link health systems, health providers, insurers, and patients to address individual and population health needs. May serve as resource to assist individuals, other health professionals, or the community, and may administer fiscal resources for health education programs.', 4, 64070, 5.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1092.00', 'Probation Officers and Correctional Treatment Specialists', 'Provide social services to assist in rehabilitation of law offenders in custody or on probation or parole. Make recommendations for actions involving formulation of rehabilitation plan and treatment of offender, including conditional release and education and employment stipulations.', 4, 66270, 3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1093.00', 'Social and Human Service Assistants', 'Assist other social and human service providers in providing client services in a wide variety of fields, such as psychology, rehabilitation, or social work, including support for families. May assist clients in identifying and obtaining available benefits and social and community services. May assist social workers with developing, organizing, and conducting programs to prevent and resolve problems relevant to substance abuse, human relationships, rehabilitation, or dependent care.', 4, 45930, 7.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-1094.00', 'Community Health Workers', 'Promote health within a community by assisting individuals to adopt healthy behaviors. Serve as an advocate for the health needs of individuals by assisting community residents in effectively communicating with healthcare providers or social service agencies. Act as liaison or advocate and implement programs that promote, maintain, and improve individual and overall community health. May deliver health-related preventive services such as blood pressure, glaucoma, and hearing screenings. May collect data to help identify community health needs.', 4, 51850, 12.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-2011.00', 'Clergy', 'Conduct religious worship and perform other spiritual functions associated with beliefs and practices of religious faith or denomination. Provide spiritual and moral guidance and assistance to members.', 5, 60810, 2.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('21-2021.00', 'Directors, Religious Activities and Education', 'Coordinate or design programs and conduct outreach to promote the religious education or activities of a denominational group. May provide counseling, guidance, and leadership relative to marital, health, financial, and religious problems.', 4, 52100, 3.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('23-1011.00', 'Lawyers', 'Represent clients in criminal and civil litigation and other legal proceedings, draw up legal documents, or manage or advise clients on legal transactions. May specialize in a single area or may practice broadly in many areas of law.', 5, 159670, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('23-1012.00', 'Judicial Law Clerks', 'Assist judges in court or by conducting research or preparing legal documents.', 5, 64920, 2.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('23-1021.00', 'Administrative Law Judges, Adjudicators, and Hearing Officers', 'Conduct hearings to recommend or make decisions on claims concerning government programs or other government-related matters. Determine liability, sanctions, or penalties, or recommend the acceptance or rejection of claims or settlements.', 5, 117860, 0, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('23-1022.00', 'Arbitrators, Mediators, and Conciliators', 'Facilitate negotiation and conflict resolution through dialogue. Resolve conflicts outside of the court system by mutual consent of parties involved.', 5, 75530, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('23-1023.00', 'Judges, Magistrate Judges, and Magistrates', 'Arbitrate, advise, adjudicate, or administer justice in a court of law. May sentence defendant in criminal cases according to government statutes or sentencing guidelines. May determine liability of defendant in civil cases. May perform wedding ceremonies.', 5, 153990, 2.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('23-2011.00', 'Paralegals and Legal Assistants', 'Assist lawyers by investigating facts, preparing legal documents, or researching legal precedent. Conduct research to support a legal proceeding, to formulate a defense, or to initiate legal action.', 3, 62890, -0.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2011.00', 'Preschool Teachers, Except Special Education', 'Instruct preschool-aged students, following curricula or lesson plans, in activities designed to promote social, physical, and intellectual growth.', 3, 38140, 4.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2012.00', 'Kindergarten Teachers, Except Special Education', 'Teach academic and social skills to kindergarten students.', 4, 62680, -0.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2021.00', 'Elementary School Teachers, Except Special Education', 'Teach academic and social skills to students at the elementary school level.', 4, 63970, -0.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2022.00', 'Middle School Teachers, Except Special and Career/Technical Education', 'Teach one or more subjects to students at the middle, intermediate, or junior high school level.', 4, 64370, -0.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2023.00', 'Career/Technical Education Teachers, Middle School', 'Teach occupational, vocational, career, or technical subjects to students at the middle, intermediate, or junior high school level.', 4, 65030, -0.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2031.00', 'Secondary School Teachers, Except Special and Career/Technical Education', 'Teach one or more subjects to students at the secondary school level.', 4, 72040, -0.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2032.00', 'Career/Technical Education Teachers, Secondary School', 'Teach occupational, vocational, career, or technical subjects to students at the secondary school level.', 4, 66270, -0.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2051.00', 'Special Education Teachers, Preschool', 'Teach academic, social, and life skills to preschool-aged students with learning, emotional, or physical disabilities. Includes teachers who specialize and work with students who are blind or have visual impairments; students who are deaf or have hearing impairments; and students with intellectual disabilities.', 4, 64830, 2.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2055.00', 'Special Education Teachers, Kindergarten', 'Teach academic, social, and life skills to kindergarten students with learning, emotional, or physical disabilities. Includes teachers who specialize and work with students who are blind or have visual impairments; students who are deaf or have hearing impairments; and students with intellectual disabilities.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2056.00', 'Special Education Teachers, Elementary School', 'Teach academic, social, and life skills to elementary school students with learning, emotional, or physical disabilities. Includes teachers who specialize and work with students who are blind or have visual impairments; students who are deaf or have hearing impairments; and students with intellectual disabilities.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2057.00', 'Special Education Teachers, Middle School', 'Teach academic, social, and life skills to middle school students with learning, emotional, or physical disabilities. Includes teachers who specialize and work with students who are blind or have visual impairments; students who are deaf or have hearing impairments; and students with intellectual disabilities.', 4, 66810, -0.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2058.00', 'Special Education Teachers, Secondary School', 'Teach academic, social, and life skills to secondary school students with learning, emotional, or physical disabilities. Includes teachers who specialize and work with students who are blind or have visual impairments; students who are deaf or have hearing impairments; and students with intellectual disabilities.', 4, 74260, -0.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-2059.01', 'Adapted Physical Education Specialists', 'Provide individualized physical education instruction or services to children, youth, or adults with exceptional physical needs due to gross motor developmental delays or other impairments.', 4, 76580, 1.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-3011.00', 'Adult Basic Education, Adult Secondary Education, and English as a Second Language Instructors', 'Teach or instruct out-of-school youths and adults in basic education, literacy, or English as a Second Language classes, or in classes for earning a high school equivalency credential.', 4, 61540, -13.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-3021.00', 'Self-Enrichment Teachers', 'Teach or instruct individuals or groups for the primary purpose of self-enrichment or recreation, rather than for an occupational objective, educational attainment, competition, or fitness.', 3, 46800, 3.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-3031.00', 'Substitute Teachers, Short-Term', 'Teach students on a short-term basis as a temporary replacement for a regular classroom teacher, typically using the regular teacher''s lesson plan.', 4, 41670, 2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-3041.00', 'Tutors', 'Instruct individual students or small groups of students in academic subjects to support formal class instruction or to prepare students for standardized or admissions tests.', 3, 43350, -0.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-4011.00', 'Archivists', 'Appraise, edit, and direct safekeeping of permanent records and historically valuable documents. Participate in research activities based on archival materials.', 5, 64550, 3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-4012.00', 'Curators', 'Administer collections, such as artwork, collectibles, historic items, or scientific specimens of museums or other institutions. May conduct instructional, research, or public service activities of institution.', 5, 63420, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-4013.00', 'Museum Technicians and Conservators', 'Restore, maintain, or prepare objects in museum collections for storage, research, or exhibit. May work with specimens such as fossils, skeletal parts, or botanicals; or artifacts, textiles, or art. May identify and record objects or install and arrange them in exhibits. Includes book or document conservators.', 5, 51440, 3.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-4022.00', 'Librarians and Media Collections Specialists', 'Administer and maintain libraries or collections of information, for public or private access through reference or borrowing. Work in a variety of settings, such as educational institutions, museums, and corporations, and with various types of informational materials, such as books, periodicals, recordings, films, and databases. Tasks may include acquiring, cataloging, and circulating library materials, and user services such as locating and organizing information, providing instruction on how to access information, and setting up and operating a library''s media equipment.', 5, 68270, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-4031.00', 'Library Technicians', 'Assist librarians by helping readers in the use of library catalogs, databases, and indexes to locate books and other materials; and by answering questions that require only brief consultation of standard reference. Compile records; sort and shelve books or other media; remove or repair damaged books or other media; register patrons; and check materials in and out of the circulation process. Replace materials in shelving area (stacks) or files. Includes bookmobile drivers who assist with providing services in mobile libraries.', 3, 44580, -6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-9021.00', 'Farm and Home Management Educators', 'Instruct and advise individuals and families engaged in agriculture, agricultural-related processes, or home management activities. Demonstrate procedures and apply research findings to advance agricultural and home management activities. May develop educational outreach programs. May instruct on either agricultural issues such as agricultural processes and techniques, pest management, and food safety, or on home management issues such as budgeting, nutrition, and child development.', 5, 60220, -3.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-9031.00', 'Instructional Coordinators', 'Develop instructional material, coordinate educational content, and incorporate current technology into instruction in order to provide guidelines to educators and instructors for developing curricula and conducting courses. May train and coach teachers. Includes educational consultants and specialists, and instructional material directors.', 5, 77440, 1.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-9042.00', 'Teaching Assistants, Preschool, Elementary, Middle, and Secondary School, Except Special Education', 'Assist a preschool, elementary, middle, or secondary school teacher with instructional duties. Serve in a position for which a teacher has primary responsibility for the design and implementation of educational programs and services.', 3, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-9043.00', 'Teaching Assistants, Special Education', 'Assist a preschool, elementary, middle, or secondary school teacher to provide academic, social, or life skills to students who have learning, emotional, or physical disabilities. Serve in a position for which a teacher has primary responsibility for the design and implementation of educational programs and services.', 3, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('25-9044.00', 'Teaching Assistants, Postsecondary', 'Assist faculty or other instructional staff in postsecondary institutions by performing instructional support activities, such as developing teaching materials, leading discussion groups, preparing and giving examinations, and grading examinations or papers.', 5, 42910, 2.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1011.00', 'Art Directors', 'Formulate design concepts and presentation approaches for visual productions and media, such as print, broadcasting, video, and film. Direct workers engaged in artwork or layout design.', 4, 114850, 4.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1012.00', 'Craft Artists', 'Create or reproduce handmade objects for sale and exhibition using a variety of techniques, such as welding, weaving, pottery, and needlecraft.', 3, 46080, 2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1013.00', 'Fine Artists, Including Painters, Sculptors, and Illustrators', 'Create original artwork using any of a wide variety of media and techniques.', 3, 55490, -2.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1014.00', 'Special Effects Artists and Animators', 'Create special effects or animations using film, video, computers, or other electronic tools and media for use in products, such as computer games, movies, music videos, and commercials.', 4, 102030, -0.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1021.00', 'Commercial and Industrial Designers', 'Design and develop manufactured products, such as cars, home appliances, and children''s toys. Combine artistic talent with research on product use, marketing, and materials to create the most functional and appealing product design.', 4, 83910, 2.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1022.00', 'Fashion Designers', 'Design clothing and accessories. Create original designs or adapt fashion trends.', 3, 80960, 0.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1024.00', 'Graphic Designers', 'Design or create graphics to meet specific commercial or promotional needs, such as packaging, displays, or logos. May use a variety of mediums to achieve artistic or decorative effects.', 4, 62960, -1.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1025.00', 'Interior Designers', 'Plan, design, and furnish the internal space of rooms or buildings. Design interior environments or create physical layouts that are practical, aesthetic, and conducive to the intended purposes. May specialize in a particular field, style, or phase of interior design.', 4, 67190, 2.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1026.00', 'Merchandise Displayers and Window Trimmers', 'Plan and erect commercial displays, such as those in windows and interiors of retail stores and at trade exhibitions.', 3, 39390, 2.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-1027.00', 'Set and Exhibit Designers', 'Design special exhibits and sets for film, video, television, and theater productions. May study scripts, confer with directors, and conduct research to determine appropriate architectural styles.', 5, 75240, 1.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2012.00', 'Producers and Directors', 'Produce or direct stage, television, radio, video, or film productions for entertainment, information, or instruction. Responsible for creative decisions, such as interpretation of script, choice of actors or guests, set design, sound, special effects, and choreography.', 4, 90360, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2012.03', 'Media Programming Directors', 'Direct and coordinate activities of personnel engaged in preparation of radio or television station program schedules and programs, such as sports or news.', 4, 90360, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2012.04', 'Talent Directors', 'Audition and interview performers to select most appropriate talent for parts in stage, television, radio, or motion picture productions.', 4, 90360, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2012.05', 'Media Technical Directors/Managers', 'Coordinate activities of technical departments, such as taping, editing, engineering, and maintenance, to produce radio or television programs.', 4, 90360, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2022.00', 'Coaches and Scouts', 'Instruct or coach groups or individuals in the fundamentals of sports for the primary purpose of competition. Demonstrate techniques and methods of participation. May evaluate athletes'' strengths and weaknesses as possible recruits or to improve the athletes'' technique to prepare them for competition. Those required to hold teaching certifications should be reported in the appropriate teaching category.', 4, 47320, 6.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2031.00', 'Dancers', 'Perform dances. May perform on stage, for broadcasting, or for video recording.', 3, null, 2.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2032.00', 'Choreographers', 'Create new dance routines. Rehearse performance of routines. May direct and stage presentations.', 3, 55310, 3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2041.00', 'Music Directors and Composers', 'Conduct, direct, plan, and lead instrumental or vocal performances by musical artists or groups, such as orchestras, bands, choirs, and glee clubs; or create original works of music.', 4, 73710, 1.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-2042.00', 'Musicians and Singers', 'Play one or more musical instruments or sing. May perform on stage, for broadcasting, or for sound or video recording.', 4, null, 0.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3011.00', 'Broadcast Announcers and Radio Disc Jockeys', 'Speak or read from scripted materials, such as news reports or commercial messages, on radio, television, or other communications media. May play and queue music, announce artist or title of performance, identify station, or interview guests.', 4, 47340, -7.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3023.00', 'News Analysts, Reporters, and Journalists', 'Narrate or write news stories, reviews, or commentary for print, broadcast, or other communications media such as newspapers, magazines, radio, or television. May collect and analyze information through interview, investigation, or observation.', 4, 62200, -5.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3031.00', 'Public Relations Specialists', 'Promote or create an intended public image for individuals, groups, or organizations. May write or select material for release to various communications media. May specialize in using social media.', 4, 74750, 1.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3041.00', 'Editors', 'Plan, coordinate, revise, or edit written material. May review proposals and drafts for possible publication.', 4, 77920, -1.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3042.00', 'Technical Writers', 'Write technical materials, such as equipment manuals, appendices, or operating and maintenance instructions. May assist in layout work.', 4, 90390, 0.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3043.00', 'Writers and Authors', 'Originate and prepare written material, such as scripts, stories, advertisements, and other material.', 4, 76910, -0.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3043.05', 'Poets, Lyricists and Creative Writers', 'Create original written works, such as scripts, essays, prose, poetry or song lyrics, for publication or performance.', 4, 76910, -0.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3091.00', 'Interpreters and Translators', 'Interpret oral or sign language, or translate written text from one language into another.', 4, 60170, 2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-3092.00', 'Court Reporters and Simultaneous Captioners', 'Use verbatim methods and equipment to capture, store, retrieve, and transcribe pretrial and trial proceedings or other information. Includes stenocaptioners who operate computerized stenographic captioning equipment to provide captions of live or prerecorded broadcasts for hearing-impaired viewers.', 3, 72420, -0.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-4011.00', 'Audio and Video Technicians', 'Set up, maintain, and dismantle audio and video equipment, such as microphones, sound speakers, connecting wires and cables, sound and mixing boards, video cameras, video monitors and servers, and related electronic equipment for live or recorded events, such as concerts, meetings, conventions, presentations, podcasts, news conferences, and sporting events.', 3, 58100, 3.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-4012.00', 'Broadcast Technicians', 'Set up, operate, and maintain the electronic equipment used to acquire, edit, and transmit audio and video for radio or television programs. Control and adjust incoming and outgoing broadcast signals to regulate sound volume, signal strength, and signal clarity. Operate satellite, microwave, or other transmitter equipment to broadcast radio or television programs.', 3, 59570, -3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-4014.00', 'Sound Engineering Technicians', 'Assemble and operate equipment to record, synchronize, mix, edit, or reproduce sound, including music, voices, or sound effects, for theater, video, film, television, podcasts, sporting events, and other productions.', 3, 73130, -3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-4015.00', 'Lighting Technicians', 'Set up, maintain, and dismantle light fixtures, lighting control devices, and the associated lighting electrical and rigging equipment used for photography, television, film, video, and live productions. May focus or operate light fixtures, or attach color filters or other lighting accessories.', 3, 68060, -4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-4021.00', 'Photographers', 'Photograph people, landscapes, merchandise, or other subjects. May use lighting equipment to enhance a subject''s appearance. May use editing software to produce finished images and prints. Includes commercial and industrial photographers, scientific photographers, and photojournalists.', 3, 44660, -0.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-4031.00', 'Camera Operators, Television, Video, and Film', 'Operate television, video, or film camera to record images or scenes for television, video, or film productions.', 3, 74990, 1.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('27-4032.00', 'Film and Video Editors', 'Edit moving images on film, video, or other media. May work with a producer or director to organize images for final production. May edit or synchronize soundtracks with images.', 4, 75420, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1011.00', 'Chiropractors', 'Assess, treat, and care for patients by manipulation of spine and musculoskeletal system. May provide spinal adjustment or address sacral or pelvic misalignment.', 5, 79200, 8.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1021.00', 'Dentists, General', 'Examine, diagnose, and treat diseases, injuries, and malformations of teeth and gums. May treat diseases of nerve, pulp, and other dental tissues affecting oral hygiene and retention of teeth. May fit dental appliances or provide preventive care.', 5, 170950, 5.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1022.00', 'Oral and Maxillofacial Surgeons', 'Perform surgery and related procedures on the hard and soft tissues of the oral and maxillofacial regions to treat diseases, injuries, or defects. May diagnose problems of the oral and maxillofacial regions. May perform surgery to improve function or appearance.', 5, 352220, 5.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1023.00', 'Orthodontists', 'Examine, diagnose, and treat dental malocclusions and oral cavity anomalies. Design and fabricate appliances to realign teeth and jaws to produce and maintain normal function and to improve appearance.', 5, 289140, 6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1024.00', 'Prosthodontists', 'Diagnose, treat, rehabilitate, design, and fit prostheses that maintain oral function, health, and appearance for patients with clinical conditions associated with teeth, oral and maxillofacial tissues, or the jaw.', 5, 311180, 5.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1031.00', 'Dietitians and Nutritionists', 'Plan and conduct food service or nutritional programs to assist in the promotion of health and control of disease. May supervise activities of a department providing quantity food services, counsel individuals, or conduct nutritional research.', 5, 76400, 7.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1041.00', 'Optometrists', 'Diagnose, manage, and treat conditions and diseases of the human eye and visual system. Examine eyes and visual system, diagnose problems or impairments, prescribe corrective lenses, and provide treatment. May prescribe therapeutic drugs to treat specific eye conditions.', 5, 136570, 9.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1051.00', 'Pharmacists', 'Dispense drugs prescribed by physicians and other health practitioners and provide information to patients about medications and their use. May advise physicians and other health practitioners on the selection, dosage, interactions, and side effects of medications.', 5, 140910, 5.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1071.00', 'Physician Assistants', 'Provide healthcare services typically performed by a physician, under the supervision of a physician. Conduct complete physicals, provide treatment, and counsel patients. May, in some cases, prescribe medication. Must graduate from an accredited educational program for physician assistants.', 5, 135880, 21.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1071.01', 'Anesthesiologist Assistants', 'Assist anesthesiologists in the administration of anesthesia for surgical and non-surgical procedures. Monitor patient status and provide patient care during surgical treatment.', 5, 135880, 21.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1081.00', 'Podiatrists', 'Diagnose and treat diseases and deformities of the human foot.', 5, 160300, 2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1122.00', 'Occupational Therapists', 'Assess, plan, and organize rehabilitative programs that help build or restore vocational, homemaking, and daily living skills, as well as general independence, to persons with disabilities or developmental delays. Use therapeutic techniques, adapt the individual''s environment, teach skills, and modify specific tasks that present barriers to the individual.', 5, 100330, 14.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1122.01', 'Low Vision Therapists, Orientation and Mobility Specialists, and Vision Rehabilitation Therapists', 'Provide therapy to patients with visual impairments to improve their functioning in daily life activities. May train patients in activities such as computer use, communication skills, or home management skills.', 5, 100330, 14.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1123.00', 'Physical Therapists', 'Assess, plan, organize, and participate in rehabilitative programs that improve mobility, relieve pain, increase strength, and improve or correct disabling conditions resulting from disease or injury.', 5, 102760, 11.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1124.00', 'Radiation Therapists', 'Provide radiation therapy to patients as prescribed by a radiation oncologist according to established practices and standards. Duties may include reviewing prescription and diagnosis; acting as liaison with physician and supportive care personnel; preparing equipment, such as immobilization, treatment, and protection devices; and maintaining records, reports, and files. May assist in dosimetry procedures and tumor localization.', 3, 105310, 2.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1125.00', 'Recreational Therapists', 'Plan, direct, or coordinate medically-approved recreation programs for patients in hospitals, nursing homes, or other institutions. Activities include sports, trips, dramatics, social activities, and crafts. May assess a patient condition and recommend appropriate recreational activity.', 4, 61960, 4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1126.00', 'Respiratory Therapists', 'Assess, treat, and care for patients with breathing disorders. Assume primary responsibility for all respiratory care modalities, including the supervision of respiratory therapy technicians. Initiate and conduct therapeutic procedures; maintain patient records; and select, assemble, check, and operate equipment.', 3, 82280, 8.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1127.00', 'Speech-Language Pathologists', 'Assess and treat persons with speech, language, voice, and fluency disorders. May select alternative communication systems and teach their use. May perform research related to speech and language problems.', 5, 97870, 16.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1128.00', 'Exercise Physiologists', 'Assess, plan, or implement fitness programs that include exercise or physical activities such as those designed to improve cardiorespiratory function, body composition, muscular strength, muscular endurance, or flexibility.', 4, 59460, 12.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1129.01', 'Art Therapists', 'Plan or conduct art therapy sessions or programs to improve clients'' physical, cognitive, or emotional well-being.', 5, 77930, 12.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1129.02', 'Music Therapists', 'Plan, organize, direct, or assess clinical and evidenced-based music therapy interventions to positively influence individuals'' physical, psychological, cognitive, or behavioral status.', 4, 77930, 12.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1131.00', 'Veterinarians', 'Diagnose, treat, or research diseases and injuries of animals. Includes veterinarians who conduct research and development, inspect livestock, or care for pets and companion animals.', 5, 130100, 9.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1141.00', 'Registered Nurses', 'Assess patient health problems and needs, develop and implement nursing care plans, and maintain medical records. Administer nursing care to ill, injured, convalescent, or disabled patients. May advise patients on health maintenance and disease prevention or provide case management. Licensing or registration required.', 4, 97550, 5.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1141.01', 'Acute Care Nurses', 'Provide advanced nursing care for patients with acute conditions such as heart attacks, respiratory distress syndrome, or shock. May care for pre- and post-operative patients or perform advanced, invasive diagnostic or therapeutic procedures.', 4, 97550, 5.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1141.02', 'Advanced Practice Psychiatric Nurses', 'Assess, diagnose, and treat individuals and families with mental health or substance use disorders or the potential for such disorders. Apply therapeutic activities, including the prescription of medication, per state regulations, and the administration of psychotherapy.', 5, 97550, 5.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1141.03', 'Critical Care Nurses', 'Provide specialized nursing care for patients in critical or coronary care units.', 4, 97550, 5.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1141.04', 'Clinical Nurse Specialists', 'Direct nursing staff in the provision of patient care in a clinical practice setting, such as a hospital, hospice, clinic, or home. Ensure adherence to established clinical policies, protocols, regulations, and standards.', 5, 97550, 5.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1151.00', 'Nurse Anesthetists', 'Administer anesthesia, monitor patient''s vital signs, and oversee patient recovery from anesthesia. May assist anesthesiologists, surgeons, other physicians, or dentists. Must be registered nurses who have specialized graduate education.', 5, 236590, 9.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1161.00', 'Nurse Midwives', 'Diagnose and coordinate all aspects of the birthing process, either independently or as part of a healthcare team. May provide well-woman gynecological care. Must have specialized, graduate nursing education.', 5, 134040, 11.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1171.00', 'Nurse Practitioners', 'Diagnose and treat acute, episodic, or chronic illness, independently or as part of a healthcare team. May focus on health promotion and disease prevention. May order, perform, or interpret diagnostic tests such as lab work and x rays. May prescribe medication. Must be registered nurses who have specialized graduate education.', 5, 132300, 41, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1181.00', 'Audiologists', 'Assess and treat persons with hearing and related disorders. May fit hearing aids and provide auditory training. May perform research related to hearing problems.', 5, 95780, 11, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1211.00', 'Anesthesiologists', 'Administer anesthetics and analgesics for pain management prior to, during, or after surgery.', 5, 391490, 3.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1212.00', 'Cardiologists', 'Diagnose, treat, manage, and prevent diseases or conditions of the cardiovascular system. May further subspecialize in interventional procedures (e.g., balloon angioplasty and stent placement), echocardiography, or electrophysiology.', 5, 496010, 4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1213.00', 'Dermatologists', 'Diagnose and treat diseases relating to the skin, hair, and nails. May perform both medical and dermatological surgery functions.', 5, 328730, 6.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1214.00', 'Emergency Medicine Physicians', 'Make immediate medical decisions and act to prevent death or further disability. Provide immediate recognition, evaluation, care, stabilization, and disposition of patients. May direct emergency medical staff in an emergency department.', 5, 335550, 3.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1215.00', 'Family Medicine Physicians', 'Diagnose, treat, and provide preventive care to individuals and families across the lifespan. May refer patients to specialists when needed for further diagnosis or treatment.', 5, 244180, 3.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1216.00', 'General Internal Medicine Physicians', 'Diagnose and provide nonsurgical treatment for a wide range of diseases and injuries of internal organ systems. Provide care mainly for adults and adolescents, and are based primarily in an outpatient care setting.', 5, 256560, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1217.00', 'Neurologists', 'Diagnose, manage, and treat disorders and diseases of the brain, spinal cord, and peripheral nerves, with a primarily nonsurgical focus.', 5, 248560, 6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1218.00', 'Obstetricians and Gynecologists', 'Provide medical care related to pregnancy or childbirth. Diagnose, treat, and help prevent diseases of women, particularly those affecting the reproductive system. May also provide general care to women. May perform both medical and gynecological surgery functions.', 5, 292910, 1.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1221.00', 'Pediatricians, General', 'Diagnose, treat, and help prevent diseases and injuries in children. May refer patients to specialists for further diagnosis or treatment, as needed.', 5, 210040, 1.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1222.00', 'Physicians, Pathologists', 'Diagnose diseases and conduct lab tests using organs, body tissues, and fluids. Includes medical examiners.', 5, 312400, 4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1223.00', 'Psychiatrists', 'Diagnose, treat, and help prevent mental disorders.', 5, 281870, 7.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1224.00', 'Radiologists', 'Diagnose and treat diseases and injuries using medical imaging techniques, such as x rays, magnetic resonance imaging (MRI), nuclear medicine, and ultrasounds. May perform minimally invasive medical procedures and tests.', 5, 420860, 3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1229.01', 'Allergists and Immunologists', 'Diagnose, treat, and help prevent allergic diseases and disease processes affecting the immune system.', 5, 265930, 3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1229.02', 'Hospitalists', 'Provide inpatient care predominantly in settings such as medical wards, acute care units, intensive care units, rehabilitation centers, or emergency rooms. Manage and coordinate patient care throughout treatment.', 5, 265930, 3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1229.03', 'Urologists', 'Diagnose, treat, and help prevent benign and malignant medical and surgical disorders of the genitourinary system and the renal glands.', 5, 265930, 3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1229.04', 'Physical Medicine and Rehabilitation Physicians', 'Diagnose and treat disorders requiring physiotherapy to provide physical, mental, and occupational rehabilitation.', 5, 265930, 3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1229.05', 'Preventive Medicine Physicians', 'Apply knowledge of general preventive medicine and public health issues to promote health care to groups or individuals, and aid in the prevention or reduction of risk of disease, injury, disability, or death. May practice population-based medicine or diagnose and treat patients in the context of clinical health promotion and disease prevention.', 5, 265930, 3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1229.06', 'Sports Medicine Physicians', 'Diagnose, treat, and help prevent injuries that occur during sporting events, athletic training, and physical activities.', 5, 265930, 3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1241.00', 'Ophthalmologists, Except Pediatric', 'Diagnose and perform surgery to treat and help prevent disorders and diseases of the eye. May also provide vision services for treatment including glasses and contacts.', 5, 300080, 4.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1242.00', 'Orthopedic Surgeons, Except Pediatric', 'Diagnose and perform surgery to treat and prevent rheumatic and other diseases in the musculoskeletal system.', 5, 358550, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1243.00', 'Pediatric Surgeons', 'Diagnose and perform surgery to treat fetal abnormalities and birth defects, diseases, and injuries in fetuses, premature and newborn infants, children, and adolescents. Includes all pediatric surgical specialties and subspecialties.', 5, 559030, 2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1291.00', 'Acupuncturists', 'Diagnose, treat, and prevent disorders by stimulating specific acupuncture points within the body using acupuncture needles. May also use cups, nutritional supplements, therapeutic massage, acupressure, and other alternative health therapies.', 5, 76040, 8.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1292.00', 'Dental Hygienists', 'Administer oral hygiene care to patients. Assess patient oral hygiene problems or needs and maintain health records. Advise patients on oral health maintenance and disease prevention. May provide advanced care such as providing fluoride treatment or administering topical anesthesia.', 3, 98100, 8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1299.01', 'Naturopathic Physicians', 'Diagnose, treat, and help prevent diseases using a system of practice that is based on the natural healing capacity of individuals. May use physiological, psychological or mechanical methods. May also use natural medicines, prescription or legend drugs, foods, herbs, or other natural remedies.', 5, 115210, 5.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-1299.02', 'Orthoptists', 'Diagnose and treat visual system disorders such as binocular vision and eye movement impairments.', 5, 115210, 5.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2011.00', 'Medical and Clinical Laboratory Technologists', 'Perform complex medical laboratory tests for diagnosis, treatment, and prevention of disease. May train or supervise staff.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2011.01', 'Cytogenetic Technologists', 'Analyze chromosomes or chromosome segments found in biological specimens, such as amniotic fluids, bone marrow, solid tumors, and blood to aid in the study, diagnosis, classification, or treatment of inherited or acquired genetic diseases. Conduct analyses through classical cytogenetic, fluorescent in situ hybridization (FISH) or array comparative genome hybridization (aCGH) techniques.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2011.02', 'Cytotechnologists', 'Stain, mount, and study cells to detect evidence of cancer, hormonal abnormalities, and other pathological conditions following established standards and practices.', 5, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2011.04', 'Histotechnologists', 'Apply knowledge of health and disease causes to evaluate new laboratory techniques and procedures to examine tissue samples. Process and prepare histological slides from tissue sections for microscopic examination and diagnosis by pathologists. May solve technical or instrument problems or assist with research studies.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2012.00', 'Medical and Clinical Laboratory Technicians', 'Perform routine medical laboratory tests for the diagnosis, treatment, and prevention of disease. May work under the supervision of a medical technologist.', 3, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2012.01', 'Histology Technicians', 'Prepare histological slides from tissue sections for microscopic examination and diagnosis by pathologists. May assist with research studies.', 3, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2031.00', 'Cardiovascular Technologists and Technicians', 'Conduct tests on pulmonary or cardiovascular systems of patients for diagnostic, therapeutic, or research purposes. May conduct or assist in electrocardiograms, cardiac catheterizations, pulmonary functions, lung capacity, and similar tests.', 3, 74310, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2032.00', 'Diagnostic Medical Sonographers', 'Produce ultrasonic recordings of internal organs for use by physicians. Includes vascular technologists.', 3, 96590, 13.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2033.00', 'Nuclear Medicine Technologists', 'Prepare, administer, and measure radioactive isotopes in therapeutic, diagnostic, and tracer studies using a variety of radioisotope equipment. Prepare stock solutions of radioactive materials and calculate doses to be administered by radiologists. Subject patients to radiation. Execute blood volume, red cell survival, and fat absorption studies following standard laboratory techniques.', 3, 101370, 4.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2034.00', 'Radiologic Technologists and Technicians', 'Take x-rays and CAT scans or administer nonradioactive materials into patient''s bloodstream for diagnostic or research purposes. Includes radiologic technologists and technicians who specialize in other scanning modalities.', 3, 80110, 5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2035.00', 'Magnetic Resonance Imaging Technologists', 'Operate Magnetic Resonance Imaging (MRI) scanners. Monitor patient safety and comfort, and view images of area being scanned to ensure quality of pictures. May administer gadolinium contrast dosage intravenously. May interview patient, explain MRI procedures, and position patient on examining table. May enter into the computer data such as patient history, anatomical area to be scanned, orientation specified, and position of entry.', 3, 95480, 7.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2036.00', 'Medical Dosimetrists', 'Generate radiation treatment plans, develop radiation dose calculations, communicate and supervise the treatment plan implementation, and consult with members of radiation oncology team.', 4, 147470, 5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2042.00', 'Emergency Medical Technicians', 'Assess injuries and illnesses and administer basic emergency medical care. May transport injured or sick persons to medical facilities.', 3, 44470, 5.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2043.00', 'Paramedics', 'Administer basic or advanced emergency medical care and assess injuries and illnesses. May administer medication intravenously, use equipment such as EKGs, or administer advanced life support to sick or injured individuals.', 3, 60600, 5.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2051.00', 'Dietetic Technicians', 'Assist in the provision of food service and nutritional programs, under the supervision of a dietitian. May plan and produce meals based on established guidelines, teach principles of food and nutrition, or counsel individuals.', 3, 37640, 2.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2052.00', 'Pharmacy Technicians', 'Prepare medications under the direction of a pharmacist. May measure, mix, count out, label, and record amounts and dosages of medications according to prescription orders.', 3, 45750, 6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2053.00', 'Psychiatric Technicians', 'Care for individuals with mental or emotional conditions or disabilities, following the instructions of physicians or other health practitioners. Monitor patients'' physical and emotional well-being and report to medical staff. May participate in rehabilitation and treatment programs, help with personal hygiene, and administer oral or injectable medications.', 3, 45130, 22.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2055.00', 'Surgical Technologists', 'Assist in operations, under the supervision of surgeons, registered nurses, or other surgical personnel. May help set up operating room, prepare and transport patients for surgery, adjust lights and equipment, pass instruments and other supplies to surgeons and surgeons'' assistants, hold retractors, cut sutures, and help count sponges, needles, supplies, and instruments.', 3, 64650, 5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2056.00', 'Veterinary Technologists and Technicians', 'Perform medical tests in a laboratory environment for use in the treatment and diagnosis of diseases in animals. Prepare vaccines and serums for prevention of diseases. Prepare tissue samples, take blood samples, and execute laboratory tests, such as urinalysis and blood counts. Clean and sterilize instruments and materials and maintain equipment and machines. May assist a veterinarian during surgery.', 3, 47380, 9.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2057.00', 'Ophthalmic Medical Technicians', 'Assist ophthalmologists by performing ophthalmic clinical functions. May administer eye exams, administer eye medications, and instruct the patient in care and use of corrective lenses.', 3, 45570, 21.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2061.00', 'Licensed Practical and Licensed Vocational Nurses', 'Care for ill, injured, or convalescing patients or persons with disabilities in hospitals, nursing homes, clinics, private homes, group homes, and similar institutions. May work under the supervision of a registered nurse. Licensing required.', 3, 64400, 3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2072.00', 'Medical Records Specialists', 'Compile, process, and maintain medical records of hospital and clinic patients in a manner consistent with medical, administrative, ethical, legal, and regulatory requirements of the healthcare system. Classify medical and healthcare concepts, including diagnosis, procedures, medical services, and equipment, into the healthcare industry''s numerical coding system. Includes medical coders.', 3, 51140, 7.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2081.00', 'Opticians, Dispensing', 'Design, measure, fit, and adapt lenses and frames for client according to written optical prescription or specification. Assist client with inserting, removing, and caring for contact lenses. Assist client with selecting frames. Measure customer for size of eyeglasses and coordinate frames with facial and eye measurements and optical prescription. Prepare work order for optical laboratory containing instructions for grinding and mounting lenses in frames. Verify exactness of finished lens spectacles. Adjust frame and lens position to fit client. May shape or reshape frames. Includes contact lens opticians.', 3, 47260, 4.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2091.00', 'Orthotists and Prosthetists', 'Design, measure, fit, and adapt orthopedic braces, appliances or prostheses, such as limbs or facial parts for patients with disabling conditions.', 5, 81110, 12.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2092.00', 'Hearing Aid Specialists', 'Select and fit hearing aids for customers. Administer and interpret tests of hearing. Assess hearing instrument efficacy. Take ear impressions and prepare, design, and modify ear molds.', 3, 65160, 19.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2099.01', 'Neurodiagnostic Technologists', 'Conduct electroneurodiagnostic (END) tests such as electroencephalograms, evoked potentials, polysomnograms, or electronystagmograms. May perform nerve conduction studies.', 3, 50290, 5.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2099.05', 'Ophthalmic Medical Technologists', 'Assist ophthalmologists by performing ophthalmic clinical functions and ophthalmic photography. Provide instruction and supervision to other ophthalmic personnel. Assist with minor surgical procedures, applying aseptic techniques and preparing instruments. May perform eye exams, administer eye medications, and instruct patients in care and use of corrective lenses.', 3, 50290, 5.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-2099.08', 'Patient Representatives', 'Assist patients in obtaining services, understanding policies and making health care decisions.', 3, 50290, 5.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-9021.00', 'Health Information Technologists and Medical Registrars', 'Apply knowledge of healthcare and information systems to assist in the design, development, and continued modification and analysis of computerized healthcare systems. Abstract, collect, and analyze treatment and followup information of patients. May educate staff and assist in problem solving to promote the implementation of the healthcare information system. May design, develop, test, and implement databases with complete history, diagnosis, treatment, and health status to help monitor diseases.', 3, 68020, 15.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-9091.00', 'Athletic Trainers', 'Evaluate and treat musculoskeletal injuries or illnesses. Provide preventive, therapeutic, emergency, and rehabilitative care.', 5, 62520, 12.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-9092.00', 'Genetic Counselors', 'Assess individual or family risk for a variety of inherited conditions, such as genetic disorders and birth defects. Provide information to other healthcare providers or to individuals and families concerned with the risk of inherited conditions. Advise individuals and families to support informed decisionmaking and coping methods for those at risk. May help conduct research related to genetic conditions or genetic counseling.', 5, 100040, 10.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-9093.00', 'Surgical Assistants', 'Assist in operations, under the supervision of surgeons. May, in accordance with state laws, help surgeons to make incisions and close surgical sites, manipulate or remove tissues, implant surgical devices or drains, suction the surgical site, place catheters, clamp or cauterize vessels or tissue, and apply dressings to surgical site.', 3, 66800, 6.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('29-9099.01', 'Midwives', 'Provide prenatal care and childbirth assistance.', 5, 65790, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('31-1131.00', 'Nursing Assistants', 'Provide or assist with basic care or support under the direction of onsite licensed nursing staff. Perform duties such as monitoring of health status, feeding, bathing, dressing, grooming, toileting, or ambulation of patients in a health or nursing facility. May include medication administration and other health-related tasks. Includes nursing care attendants, nursing aides, and nursing attendants.', 3, 42260, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('31-2011.00', 'Occupational Therapy Assistants', 'Assist occupational therapists in providing occupational therapy treatments and procedures. May, in accordance with state laws, assist in development of treatment plans, carry out routine functions, direct activity programs, and document the progress of treatments. Generally requires formal training.', 3, 72300, 21.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('31-2012.00', 'Occupational Therapy Aides', 'Under close supervision of an occupational therapist or occupational therapy assistant, perform only delegated, selected, or routine tasks in specific situations. These duties include preparing patient and treatment room.', 3, 39160, 3.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('31-2021.00', 'Physical Therapist Assistants', 'Assist physical therapists in providing physical therapy treatments and procedures. May, in accordance with state laws, assist in the development of treatment plans, carry out routine functions, document the progress of treatment, and modify specific treatments in accordance with patient status and within the scope of treatment plans established by a physical therapist. Generally requires formal training.', 3, 68380, 23, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('31-9011.00', 'Massage Therapists', 'Perform therapeutic massages of soft tissues and joints. May assist in the assessment of range of motion and muscle strength, or propose client therapy plans.', 3, 58450, 15.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('31-9091.00', 'Dental Assistants', 'Perform limited clinical duties under the direction of a dentist. Clinical duties may include equipment preparation and sterilization, preparing patients for treatment, assisting the dentist during treatment, and providing patients with instructions for oral healthcare procedures. May perform administrative duties such as scheduling appointments, maintaining medical records, billing, and coding information for insurance purposes.', 3, 48070, 7.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('31-9092.00', 'Medical Assistants', 'Perform administrative and certain clinical duties under the direction of a physician. Administrative duties may include scheduling appointments, maintaining medical records, billing, and coding information for insurance purposes. Clinical duties may include taking and recording vital signs and medical histories, preparing patients for examination, drawing blood, and administering medications as directed by physician.', 3, 45690, 12.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('31-9094.00', 'Medical Transcriptionists', 'Transcribe medical reports recorded by physicians and other healthcare practitioners using various electronic devices, covering office visits, emergency room visits, diagnostic imaging studies, operations, chart reviews, and final summaries. Transcribe dictated reports and translate abbreviations into fully understandable form. Edit as necessary and return reports in either printed or electronic form for review and signature, or correction.', 3, 40410, -4.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('31-9097.00', 'Phlebotomists', 'Draw blood for tests, transfusions, donations, or research. May explain the procedure to patients and assist in the recovery of patients with adverse reactions.', 3, 45230, 6.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('31-9099.01', 'Speech-Language Pathology Assistants', 'Assist speech-language pathologists in the assessment and treatment of speech, language, voice, and fluency disorders. Implement speech and language programs or activities as planned and directed by speech-language pathologists. Monitor the use of alternative communication devices and systems.', 3, 48430, 4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('33-1011.00', 'First-Line Supervisors of Correctional Officers', 'Directly supervise and coordinate activities of correctional officers and jailers.', 3, 77970, -2.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('33-1021.00', 'First-Line Supervisors of Firefighting and Prevention Workers', 'Directly supervise and coordinate activities of workers engaged in firefighting and fire prevention and control.', 3, 93530, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('33-2021.00', 'Fire Inspectors and Investigators', 'Inspect buildings to detect fire hazards and enforce local ordinances and state laws, or investigate and gather facts to determine cause of fires and explosions.', 3, 75920, 4.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('33-2022.00', 'Forest Fire Inspectors and Prevention Specialists', 'Enforce fire regulations, inspect forest for fire hazards, and recommend forest fire prevention or control measures. May report forest fires and weather conditions.', 3, 56870, 13.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('33-3011.00', 'Bailiffs', 'Maintain order in courts of law.', 3, 56600, -1.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('33-3021.00', 'Detectives and Criminal Investigators', 'Conduct investigations related to suspected violations of federal, state, or local laws to prevent or solve crimes.', 3, 93790, 0.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('33-3021.02', 'Police Identification and Records Officers', 'Collect evidence at crime scene, classify and identify fingerprints, and photograph evidence for use in criminal and civil cases.', 3, 93790, 0.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('33-3021.06', 'Intelligence Analysts', 'Gather, analyze, or evaluate information from a variety of sources, such as law enforcement databases, surveillance, intelligence networks or geographic information systems. Use intelligence data to anticipate and prevent organized crime activities, such as terrorism.', 4, 93790, 0.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('33-3031.00', 'Fish and Game Wardens', 'Patrol assigned area to prevent fish and game law violations. Investigate reports of damage to crops or property by wildlife. Compile biological data.', 3, 74060, -5.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('33-3051.00', 'Police and Sheriff''s Patrol Officers', 'Maintain order and protect life and property by enforcing local, tribal, state, or federal laws and ordinances. Perform a combination of the following duties: patrol a specific area; direct traffic; issue traffic summonses; investigate accidents; apprehend and arrest suspects, or serve legal processes of courts. Includes police officers working at educational institutions.', 3, 76210, 3.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('33-3051.04', 'Customs and Border Protection Officers', 'Investigate and inspect persons, common carriers, goods, and merchandise, arriving in or departing from the United States or between states to detect violations of immigration and customs laws and regulations.', 3, 76210, 3.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('33-3052.00', 'Transit and Railroad Police', 'Protect and police railroad and transit property, employees, or passengers.', 3, 90230, 3.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('33-9021.00', 'Private Detectives and Investigators', 'Gather, analyze, compile, and report information regarding individuals or organizations to clients, or detect occurrences of unlawful acts or infractions of rules in private establishment.', 3, 51220, 5.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('35-1011.00', 'Chefs and Head Cooks', 'Direct and may participate in the preparation, seasoning, and cooking of salads, soups, fish, meats, vegetables, desserts, or other foods. May plan and price menu items, order supplies, and keep records and accounts.', 3, 62470, 6.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('35-2013.00', 'Cooks, Private Household', 'Prepare meals in private homes. Includes personal chefs.', 3, 47940, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('37-1012.00', 'First-Line Supervisors of Landscaping, Lawn Service, and Groundskeeping Workers', 'Directly supervise and coordinate activities of workers engaged in landscaping or groundskeeping activities. Work may involve reviewing contracts to ascertain service, machine, and workforce requirements; answering inquiries from potential customers regarding methods, material, and price ranges; and preparing estimates according to labor, material, and machine costs.', 3, 58430, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('37-2011.00', 'Janitors and Cleaners, Except Maids and Housekeeping Cleaners', 'Keep buildings in clean and orderly condition. Perform heavy cleaning duties, such as cleaning floors, shampooing rugs, washing walls and glass, and removing rubbish. Duties may include tending furnace and boiler, performing routine maintenance activities, notifying management of need for repairs, and cleaning snow or debris from sidewalk.', 3, 36840, 2.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('39-1022.00', 'First-Line Supervisors of Personal Service Workers', 'Supervise and coordinate activities of personal service workers.', 3, 48590, 6.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('39-4011.00', 'Embalmers', 'Prepare bodies for interment in conformity with legal requirements.', 3, 58780, 0.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('39-4031.00', 'Morticians, Undertakers, and Funeral Arrangers', 'Perform various tasks to arrange and direct individual funeral services, such as coordinating transportation of body to mortuary, interviewing family or other authorized person to arrange details, selecting pallbearers, aiding with the selection of officials for religious rites, and providing transportation for mourners.', 3, 55010, 3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('39-5011.00', 'Barbers', 'Provide barbering services, such as cutting, trimming, shampooing, and styling hair; trimming beards; or giving shaves.', 3, 38210, 3.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('39-5012.00', 'Hairdressers, Hairstylists, and Cosmetologists', 'Provide beauty services, such as cutting, coloring, and styling hair, and massaging and treating scalp. May shampoo hair, apply makeup, dress wigs, remove hair, and provide nail and skincare services.', 3, 35790, 7.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('39-5091.00', 'Makeup Artists, Theatrical and Performance', 'Apply makeup to performers to reflect period, setting, and situation of their role.', 3, 97150, 6.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('39-5094.00', 'Skincare Specialists', 'Provide skincare treatments to face and body to enhance an individual''s appearance. Includes electrologists and laser hair removal specialists.', 3, 45330, 8.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('39-7011.00', 'Tour Guides and Escorts', 'Escort individuals or groups on sightseeing tours or through places of interest, such as industrial establishments, public buildings, and art galleries.', 3, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('39-9031.00', 'Exercise Trainers and Group Fitness Instructors', 'Instruct or coach groups or individuals in exercise activities for the primary purpose of personal fitness. Demonstrate techniques and form, observe participants, and explain to them corrective measures necessary to improve their skills. Develop and implement individualized approaches to exercise.', 3, 47160, 7.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('39-9032.00', 'Recreation Workers', 'Conduct recreation activities with groups in public, private, or volunteer agencies or recreation facilities. Organize and promote activities, such as arts and crafts, sports, games, music, dramatics, social recreation, camping, and hobbies, taking into account the needs and interests of individual members.', 4, 36560, 4.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('39-9041.00', 'Residential Advisors', 'Coordinate activities in resident facilities in secondary school and college dormitories, group homes, or similar establishments. Order supplies and determine need for maintenance, repairs, and furnishings. May maintain household records and assign rooms. May assist residents with problem solving or refer them to counseling resources.', 3, 42240, 3.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('41-1012.00', 'First-Line Supervisors of Non-Retail Sales Workers', 'Directly supervise and coordinate activities of sales workers other than retail sales workers. May perform duties such as budgeting, accounting, and personnel work, in addition to supervisory duties.', 4, 87520, 0.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('41-3011.00', 'Advertising Sales Agents', 'Sell or solicit advertising space, time, or media in publications, signage, TV, radio, or Internet establishments or public spaces.', 3, 64820, -7.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('41-3021.00', 'Insurance Sales Agents', 'Sell life, property, casualty, health, automotive, or other types of insurance. May refer clients to independent brokers, work as an independent broker, or be employed by an insurance company.', 4, 62280, 3.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('41-3031.00', 'Securities, Commodities, and Financial Services Sales Agents', 'Buy and sell securities or commodities in investment and trading firms, or provide financial services to businesses and individuals. May advise customers about stocks, bonds, mutual funds, commodities, and market conditions.', 4, 78660, 1.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('41-3041.00', 'Travel Agents', 'Plan and sell transportation and accommodations for customers. Determine destination, modes of transportation, travel dates, costs, and accommodations required. May also describe, plan, and arrange itineraries and sell tour packages. May assist in resolving clients'' travel problems.', 3, 50160, 0.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('41-4011.00', 'Sales Representatives, Wholesale and Manufacturing, Technical and Scientific Products', 'Sell goods for wholesalers or manufacturers where technical or scientific knowledge is required in such areas as biology, engineering, chemistry, and electronics, normally obtained from at least 2 years of postsecondary education.', 4, 104920, 1.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('41-4011.07', 'Solar Sales Representatives and Assessors', 'Contact new or existing customers to determine their solar equipment needs, suggest systems or equipment, or estimate costs.', 3, 104920, 1.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('41-4012.00', 'Sales Representatives, Wholesale and Manufacturing, Except Technical and Scientific Products', 'Sell goods for wholesalers or manufacturers to businesses or groups of individuals. Work requires substantial knowledge of items sold.', 4, 72080, -0.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('41-9021.00', 'Real Estate Brokers', 'Operate real estate office, or work for commercial real estate firm, overseeing real estate transactions. Other duties usually include selling real estate or renting properties and arranging loans.', 4, 73220, 0.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('41-9031.00', 'Sales Engineers', 'Sell business goods or services, the selling of which requires a technical background equivalent to a baccalaureate degree in engineering.', 4, 124900, 2.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('43-1011.00', 'First-Line Supervisors of Office and Administrative Support Workers', 'Directly supervise and coordinate the activities of clerical and administrative support workers.', 3, 69500, 0.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('43-3031.00', 'Bookkeeping, Accounting, and Auditing Clerks', 'Compute, classify, and record numerical data to keep financial records complete. Perform any combination of routine calculating, posting, and verifying duties to obtain primary financial data for use in maintaining accounting records. May also check the accuracy of figures, calculations, and postings pertaining to business transactions recorded by other workers.', 3, 50670, -5.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('43-3051.00', 'Payroll and Timekeeping Clerks', 'Compile and record employee time and payroll data. May compute employees'' time worked, production, and commission. May compute and post wages and deductions, or prepare paychecks.', 3, 58260, -15.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('43-4011.00', 'Brokerage Clerks', 'Perform duties related to the purchase, sale, or holding of securities. Duties include writing orders for stock purchases or sales, computing transfer taxes, verifying stock transactions, accepting and delivering securities, tracking stock price fluctuations, computing equity, distributing dividends, and keeping records of daily transactions and holdings.', 3, 65750, -7.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('43-4061.00', 'Eligibility Interviewers, Government Programs', 'Determine eligibility of persons applying to receive assistance from government programs and agency resources, such as welfare, unemployment benefits, social security, and public housing.', 3, 54210, 1.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('43-4111.00', 'Interviewers, Except Eligibility and Loan', 'Interview persons by telephone, mail, in person, or by other means for the purpose of completing forms, applications, or questionnaires. Ask specific questions, record answers, and assist persons with completing form. May sort, classify, and file forms.', 3, 45920, -10.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('43-4131.00', 'Loan Interviewers and Clerks', 'Interview loan applicants to elicit information; investigate applicants'' backgrounds and verify references; prepare loan request papers; and forward findings, reports, and documents to appraisal department. Review loan papers to ensure completeness, and complete transactions between loan establishment, borrowers, and sellers upon approval of loan.', 3, 50020, -2.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('43-4141.00', 'New Accounts Clerks', 'Interview persons desiring to open accounts in financial institutions. Explain account services available to prospective customers and assist them in preparing applications.', 3, 47670, -6.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('43-4161.00', 'Human Resources Assistants, Except Payroll and Timekeeping', 'Compile and keep personnel records. Record data for each employee, such as address, weekly earnings, absences, amount of sales or production, supervisory reports, and date of and reason for termination. May prepare reports for employment records, file employment records, or search employee files and furnish information to authorized persons.', 3, 50610, -6.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('43-6011.00', 'Executive Secretaries and Executive Administrative Assistants', 'Provide high-level administrative support by conducting research, preparing statistical reports, and handling information requests, as well as performing routine administrative functions such as preparing correspondence, receiving visitors, arranging conference calls, and scheduling meetings. May also train and supervise lower-level clerical staff.', 3, 76590, 0, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('43-6012.00', 'Legal Secretaries and Administrative Assistants', 'Perform secretarial duties using legal terminology, procedures, and documents. Prepare legal papers and correspondence, such as summonses, complaints, motions, and subpoenas. May also assist with legal research.', 3, 55570, -5.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('43-9031.00', 'Desktop Publishers', 'Format typescript and graphic elements using computer software to produce publication-ready material.', 3, 55290, -14.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('43-9081.00', 'Proofreaders and Copy Markers', 'Read transcript or proof type setup to detect and mark for correction any grammatical, typographical, or compositional errors. Excludes workers whose primary duty is editing copy. Includes proofreaders of braille.', 4, 51120, -0.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('43-9111.00', 'Statistical Assistants', 'Compile and compute data according to statistical formulas for use in statistical studies. May perform actuarial computations and compile charts and graphs for use by actuaries. Includes actuarial clerks.', 4, 50330, -1.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('45-1011.00', 'First-Line Supervisors of Farming, Fishing, and Forestry Workers', 'Directly supervise and coordinate the activities of agricultural, forestry, aquacultural, and related workers.', 3, 59320, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('47-1011.00', 'First-Line Supervisors of Construction Trades and Extraction Workers', 'Directly supervise and coordinate activities of construction or extraction workers.', 3, 79920, 5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('47-1011.03', 'Solar Energy Installation Managers', 'Direct work crews installing residential or commercial solar photovoltaic or thermal systems.', 3, 79920, 5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('47-2111.00', 'Electricians', 'Install, maintain, and repair electrical wiring, equipment, and fixtures. Ensure that work is in accordance with relevant codes. May install or service street lights, intercom systems, or electrical control systems.', 3, 63190, 9.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('47-2152.00', 'Plumbers, Pipefitters, and Steamfitters', 'Assemble, install, alter, and repair pipelines or pipe systems that carry water, steam, air, or other liquids or gases. May install heating and cooling equipment and mechanical control systems. Includes sprinkler fitters.', 3, 63800, 6.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('47-2152.04', 'Solar Thermal Installers and Technicians', 'Install or repair solar energy systems designed to collect, store, and circulate solar-heated water for residential, commercial or industrial use.', 3, 63800, 6.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('47-4011.00', 'Construction and Building Inspectors', 'Inspect structures using engineering skills to determine structural soundness and compliance with specifications, building codes, and other regulations. Inspections may be general in nature or may be limited to a specific area, such as electrical systems or plumbing.', 3, 74690, 0, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('47-4011.01', 'Energy Auditors', 'Conduct energy audits of buildings, building systems, or process systems. May also conduct investment grade audits of buildings or systems.', 3, 74690, 0, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('47-4021.00', 'Elevator and Escalator Installers and Repairers', 'Assemble, install, repair, or maintain electric or hydraulic freight or passenger elevators, escalators, or dumbwaiters.', 3, 109910, 5.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-1011.00', 'First-Line Supervisors of Mechanics, Installers, and Repairers', 'Directly supervise and coordinate the activities of mechanics, installers, and repairers. May also advise customers on recommended services. Excludes team or work leaders.', 3, 79860, 4.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-2021.00', 'Radio, Cellular, and Tower Equipment Installers and Repairers', 'Repair, install, or maintain mobile or stationary radio transmitting, broadcasting, and receiving equipment, and two-way radio communications systems used in cellular telecommunications, mobile broadband, ship-to-shore, aircraft-to-ground communications, and radio equipment in service and emergency vehicles. May test and analyze network coverage.', 3, 63520, 1.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-2022.00', 'Telecommunications Equipment Installers and Repairers, Except Line Installers', 'Install, set up, rearrange, or remove switching, distribution, routing, and dialing equipment used in central offices or headends. Service or repair telephone, cable television, Internet, and other communications equipment on customers'' property. May install communications equipment or communications wiring in buildings.', 3, 63890, -3.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-2091.00', 'Avionics Technicians', 'Install, inspect, test, adjust, or repair avionics equipment, such as radar, radio, navigation, and missile control systems in aircraft or space vehicles.', 3, 82280, 9.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-2092.00', 'Electric Motor, Power Tool, and Related Repairers', 'Repair, maintain, or install electric motors, wiring, or switches.', 3, 56210, 4.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-2093.00', 'Electrical and Electronics Installers and Repairers, Transportation Equipment', 'Install, adjust, or maintain mobile electronics communication equipment, including sound, sonar, security, navigation, and surveillance systems on trains, watercraft, or other mobile equipment.', 3, 84890, 5.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-2094.00', 'Electrical and Electronics Repairers, Commercial and Industrial Equipment', 'Repair, test, adjust, or install electronic equipment, such as industrial controls, transmitters, and antennas.', 3, 74090, 0.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-2095.00', 'Electrical and Electronics Repairers, Powerhouse, Substation, and Relay', 'Inspect, test, repair, or maintain electrical equipment in generating stations, substations, and in-service relays.', 3, 103020, 9.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-2096.00', 'Electronic Equipment Installers and Repairers, Motor Vehicles', 'Install, diagnose, or repair communications, sound, security, or navigation equipment in motor vehicles.', 3, 48420, -14.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-2097.00', 'Audiovisual Equipment Installers and Repairers', 'Install, repair, or adjust audio or television receivers, stereo systems, camcorders, video systems, or other electronic entertainment equipment in homes or other venues. May perform routine maintenance.', 3, 52600, 4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-2098.00', 'Security and Fire Alarm Systems Installers', 'Install, program, maintain, and repair security and fire alarm wiring and equipment. Ensure that work is in accordance with relevant codes.', 3, 60070, 6.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-3011.00', 'Aircraft Mechanics and Service Technicians', 'Diagnose, adjust, repair, or overhaul aircraft engines and assemblies, such as hydraulic and pneumatic systems.', 3, 79870, 5.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-3023.00', 'Automotive Service Technicians and Mechanics', 'Diagnose, adjust, repair, or overhaul automotive vehicles.', 3, 50620, 5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-3031.00', 'Bus and Truck Mechanics and Diesel Engine Specialists', 'Diagnose, adjust, repair, or overhaul buses and trucks, or maintain and repair any type of diesel engines. Includes mechanics working primarily with automobile or marine diesel engines.', 3, 61770, 3.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-3041.00', 'Farm Equipment Mechanics and Service Technicians', 'Diagnose, adjust, repair, or overhaul farm machinery and vehicles, such as tractors, harvesters, dairy equipment, and irrigation systems.', 3, 56550, 10.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-3042.00', 'Mobile Heavy Equipment Mechanics, Except Engines', 'Diagnose, adjust, repair, or overhaul mobile mechanical, hydraulic, and pneumatic equipment, such as cranes, bulldozers, graders, and conveyors, used in construction, logging, and mining.', 3, 65510, 6.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-3051.00', 'Motorboat Mechanics and Service Technicians', 'Repair and adjust electrical and mechanical equipment of inboard or inboard-outboard boat engines.', 3, 57550, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-3052.00', 'Motorcycle Mechanics', 'Diagnose, adjust, repair, or overhaul motorcycles, scooters, mopeds, dirt bikes, or similar motorized vehicles.', 3, 48580, 2.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-9012.00', 'Control and Valve Installers and Repairers, Except Mechanical Door', 'Install, repair, and maintain mechanical regulating and controlling devices, such as electric meters, gas regulators, thermostats, safety and flow valves, and other mechanical governors.', 3, 74340, 4.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-9021.00', 'Heating, Air Conditioning, and Refrigeration Mechanics and Installers', 'Install or repair heating, central air conditioning, HVAC, or refrigeration systems, including oil burners, hot-air furnaces, and heating stoves.', 3, 61010, 10.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-9041.00', 'Industrial Machinery Mechanics', 'Repair, install, adjust, or maintain industrial production and processing machinery or refinery and pipeline distribution systems. May also install, dismantle, or move machinery and heavy equipment according to plans.', 3, 64520, 17.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-9043.00', 'Maintenance Workers, Machinery', 'Lubricate machinery, change parts, or perform other routine machinery maintenance.', 3, 60850, -1.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-9061.00', 'Camera and Photographic Equipment Repairers', 'Repair and adjust cameras and photographic equipment, including commercial video and motion picture camera equipment.', 3, 52720, -15.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-9062.00', 'Medical Equipment Repairers', 'Test, adjust, or repair biomedical or electromedical equipment.', 3, 61660, 12.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-9063.00', 'Musical Instrument Repairers and Tuners', 'Repair percussion, stringed, reed, or wind instruments. May specialize in one area, such as piano tuning.', 3, 46420, 1.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-9064.00', 'Watch and Clock Repairers', 'Repair, clean, and adjust mechanisms of timing instruments, such as watches and clocks. Includes watchmakers, watch technicians, and mechanical timepiece repairers.', 3, 67230, -0.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-9071.00', 'Maintenance and Repair Workers, General', 'Perform work involving the skills of two or more maintenance or craft occupations to keep machines, mechanical equipment, or the structure of a building in repair. Duties may involve pipe fitting; HVAC maintenance; insulating; welding; machining; carpentry; repairing electrical or mechanical equipment; installing, aligning, and balancing new equipment; and repairing buildings, floors, or stairs.', 3, 49590, 4.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-9081.00', 'Wind Turbine Service Technicians', 'Inspect, diagnose, adjust, or repair wind turbines. Perform maintenance on wind turbine equipment including resolving electrical, mechanical, and hydraulic malfunctions.', 3, 64120, 29.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-9092.00', 'Commercial Divers', 'Work below surface of water, using surface-supplied air or scuba equipment to inspect, repair, remove, or install equipment and structures. May use a variety of power and hand tools, such as drills, sledgehammers, torches, and welding equipment. May conduct tests or experiments, rig explosives, or photograph structures or marine life.', 3, 72990, 4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('49-9097.00', 'Signal and Track Switch Repairers', 'Install, inspect, test, maintain, or repair electric gate crossings, signals, signal equipment, track switches, section lines, or intercommunications systems within a railroad system.', 3, 92460, 1.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('51-1011.00', 'First-Line Supervisors of Production and Operating Workers', 'Directly supervise and coordinate the activities of production and operating workers, such as inspectors, precision workers, machine setters and operators, assemblers, fabricators, and plant and system operators. Excludes team or work leaders.', 3, 74450, 1.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('51-4041.00', 'Machinists', 'Set up and operate a variety of machine tools to produce precision parts and instruments out of metal. Includes precision instrument makers who fabricate, modify, or repair mechanical instruments. May also fabricate and modify parts to make or repair machine tools or maintain industrial machines, applying knowledge of mechanics, mathematics, metal properties, layout, and machining procedures.', 3, 58750, 1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('51-4061.00', 'Model Makers, Metal and Plastic', 'Set up and operate machines, such as lathes, milling and engraving machines, and jig borers to make working models of metal or plastic objects. Includes template makers.', 3, 63340, -17.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('51-4062.00', 'Patternmakers, Metal and Plastic', 'Lay out, machine, fit, and assemble castings and parts to metal or plastic foundry patterns, core boxes, or match plates.', 3, 58000, -22.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('51-4111.00', 'Tool and Die Makers', 'Analyze specifications, lay out metal stock, set up and operate machine tools, and fit and assemble parts to make and repair dies, cutting tools, jigs, fixtures, gauges, and machinists'' hand tools.', 3, 64050, -9.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('51-5111.00', 'Prepress Technicians and Workers', 'Format and proof text and images submitted by designers and clients into finished pages that can be printed. Includes digital and photo typesetting. May produce printing plates.', 3, 48690, -15.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('51-6092.00', 'Fabric and Apparel Patternmakers', 'Draw and construct sets of precision master fabric patterns or layouts. May also mark and cut fabrics and apparel.', 3, 62750, -15, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('51-7031.00', 'Model Makers, Wood', 'Construct full-size and scale wooden precision models of products. Includes wood jig builders and loft workers.', 3, 56550, -3.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('51-7032.00', 'Patternmakers, Wood', 'Plan, lay out, and construct wooden unit or sectional patterns used in forming sand molds for castings.', 3, 49630, -2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('51-8011.00', 'Nuclear Power Reactor Operators', 'Operate or control nuclear reactors. Move control rods, start and stop equipment, monitor and adjust controls, and record data in logs. Implement emergency procedures when needed. May respond to abnormalities, determine cause, and recommend corrective action.', 3, 122890, -5.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('51-8012.00', 'Power Distributors and Dispatchers', 'Coordinate, regulate, or distribute electricity or steam.', 3, 106730, 1.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('51-8013.04', 'Hydroelectric Plant Technicians', 'Monitor and control activities associated with hydropower generation. Operate plant equipment, such as turbines, pumps, valves, gates, fans, electric control boards, and battery banks. Monitor equipment operation and performance and make necessary adjustments to ensure optimal performance. Perform equipment maintenance and repair as necessary.', 3, 102040, -5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('51-8021.00', 'Stationary Engineers and Boiler Operators', 'Operate or maintain stationary engines, boilers, or other mechanical equipment to provide utilities for buildings or industrial processes. Operate equipment such as steam engines, generators, motors, turbines, and steam boilers.', 3, 78620, 3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('51-9071.00', 'Jewelers and Precious Stone and Metal Workers', 'Design, fabricate, adjust, repair, or appraise jewelry, gold, silver, other precious metals, or gems.', 3, 52540, -3.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('51-9071.06', 'Gem and Diamond Workers', 'Fabricate, finish, or evaluate the quality of gems and diamonds used in jewelry or industrial tools.', 3, 52540, -3.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('51-9195.05', 'Potters, Manufacturing', 'Operate production machines such as pug mill, jigger machine, or potter''s wheel to process clay in manufacture of ceramic, pottery and stoneware products.', 3, 46170, 5.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('53-1043.00', 'First-Line Supervisors of Material-Moving Machine and Vehicle Operators', 'Directly supervise and coordinate activities of material-moving machine and vehicle operators and helpers.', 3, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('53-1044.00', 'First-Line Supervisors of Passenger Attendants', 'Supervise and coordinate activities of passenger attendants.', 3, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('53-2011.00', 'Airline Pilots, Copilots, and Flight Engineers', 'Pilot and navigate the flight of fixed-wing aircraft, usually on scheduled air carrier routes, for the transport of passengers and cargo. Requires Federal Air Transport certificate and rating for specific aircraft type used. Includes regional, national, and international airline pilots and flight instructors of airline pilots.', 4, 232140, 8.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('53-2012.00', 'Commercial Pilots', 'Pilot and navigate the flight of fixed-wing aircraft on nonscheduled air carrier routes, or helicopters. Requires Commercial Pilot certificate. Includes charter pilots with similar certification, and air ambulance and air tour pilots. Excludes regional, national, and international airline pilots.', 3, 123220, 5.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('53-2021.00', 'Air Traffic Controllers', 'Control air traffic on and within vicinity of airport, and movement of air traffic between altitude sectors and control centers, according to established procedures and policies. Authorize, regulate, and control commercial airline flights according to government or company regulations to expedite and ensure flight safety.', 3, 148080, 1.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('53-2022.00', 'Airfield Operations Specialists', 'Ensure the safe takeoff and landing of commercial and military aircraft. Duties include coordination between air-traffic control and maintenance personnel, dispatching, using airfield landing and navigational aids, implementing airfield safety procedures, monitoring and maintaining flight records, and applying knowledge of weather information.', 3, 56850, 7.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('53-5021.00', 'Captains, Mates, and Pilots of Water Vessels', 'Command or supervise operations of ships and water vessels, such as tugboats and ferryboats. Required to hold license issued by U.S. Coast Guard.', 3, 92460, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('53-5031.00', 'Ship Engineers', 'Supervise and coordinate activities of crew engaged in operating and maintaining engines, boilers, deck machinery, and electrical, sanitary, and refrigeration equipment aboard ship.', 3, 109530, 2.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('53-6041.00', 'Traffic Technicians', 'Conduct field studies to determine traffic volume, speed, effectiveness of signals, adequacy of lighting, and other factors influencing traffic conditions, under direction of traffic engineer.', 3, 59090, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('53-6051.00', 'Transportation Inspectors', 'Inspect equipment or goods in connection with the safe transport of cargo or people. Includes rail transportation inspectors, such as freight inspectors, rail inspectors, and other inspectors of transportation vehicles not elsewhere classified.', 4, 92100, 2.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('53-6051.01', 'Aviation Inspectors', 'Inspect aircraft, maintenance procedures, air navigational aids, air traffic controls, and communications equipment to ensure conformance with Federal safety regulations.', 3, 92100, 2.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('53-7021.00', 'Crane and Tower Operators', 'Operate mechanical boom and cable or tower and cable equipment to lift and move materials, machines, or products in many directions.', 3, 68080, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']);
