insert into top_jobs_tables (version, rubric_version_id, self_map, open_list) values (1, (select id from rubric_versions where version = 1), '{"problem_solving":{"execution":0.5,"adaptability":0.5},"decision_making_under_pressure":{"resilience":0.5,"leadership":0.5},"strategic_game_iq":{"adaptability":0.5,"execution":0.5},"learning_agility":{"adaptability":1},"attention_to_detail":{"discipline":0.5,"execution":0.5},"analytical_thinking":{"execution":0.5,"adaptability":0.5},"discipline":{"discipline":1},"work_ethic":{"discipline":1},"consistency":{"discipline":1},"accountability":{"discipline":0.5,"leadership":0.5},"time_management":{"discipline":0.5,"execution":0.5},"dependability":{"discipline":1},"team_communication":{"communication":1},"leadership":{"leadership":1},"coachability":{"adaptability":0.5,"communication":0.5},"cooperation":{"communication":1},"conflict_resolution":{"communication":0.5,"leadership":0.5},"social_emotional_awareness":{"communication":1},"mental_toughness":{"resilience":1},"resilience":{"resilience":1},"adaptability":{"adaptability":1},"competitive_drive":{"execution":1},"focus":{"discipline":0.5,"execution":0.5},"stress_pressure_tolerance":{"resilience":1}}', '[{"code":"13-1082.00","reason":"Runs projects against deadlines with a team: the season, in a business setting."},{"code":"15-1299.09","reason":"Leads technical teams through sprints; coachable, organized athletes fit the Scrum Master path."},{"code":"13-1111.00","reason":"Breaks down performance and finds what to fix, like film study for an organization."},{"code":"15-2051.01","reason":"Turns data into decisions; rewards discipline and attention to detail."},{"code":"11-2022.00","reason":"Leads a sales team to a number; competitive drive and leadership."},{"code":"41-4012.00","reason":"Competitive, goal-driven, resilient through rejection."},{"code":"41-4011.00","reason":"Learns a complex product and competes for results."},{"code":"41-3031.00","reason":"High pressure, measurable results, and relationship building."},{"code":"41-3021.00","reason":"Self-driven, resilient, and built on trust with clients."},{"code":"41-1012.00","reason":"Coaches a sales team: leadership on the floor."},{"code":"11-1021.00","reason":"Keeps a whole operation running; leadership and execution."},{"code":"11-3071.04","reason":"Coordinates many moving parts under pressure."},{"code":"13-1081.00","reason":"Plans and executes the logistics behind every game day."},{"code":"13-1081.02","reason":"Analyzes and improves how things move; discipline and detail."},{"code":"11-3121.00","reason":"Builds teams and culture; leadership and communication."},{"code":"13-1071.00","reason":"Recruits and develops people, as a team captain does."},{"code":"13-1151.00","reason":"Teaches and develops others: coaching in a company."},{"code":"11-3131.00","reason":"Leads development programs; leadership and communication."},{"code":"13-1161.00","reason":"Studies competitors and audiences; scouting for a business."},{"code":"11-2021.00","reason":"Leads campaigns to measurable goals."},{"code":"27-3031.00","reason":"Comfortable with media and representing a team in public."},{"code":"11-2032.00","reason":"Leads communication for an organization under scrutiny."},{"code":"13-1121.00","reason":"Executes complex events on a fixed date; game-day experience."},{"code":"11-9072.00","reason":"Runs recreation and entertainment programs; natural athlete fit."},{"code":"13-1023.00","reason":"Negotiates and manages suppliers; competitive and detail-minded."},{"code":"13-1041.00","reason":"Lives by the rulebook; athletes know compliance from NCAA rules."},{"code":"11-9151.00","reason":"Leads programs that serve the community; citizenship and leadership."},{"code":"13-2052.00","reason":"Builds client trust and long-term plans; discipline and communication."},{"code":"27-2022.00","reason":"The direct path: coaching and developing athletes."},{"code":"11-3013.00","reason":"Runs facilities and venues; operations and accountability."},{"code":"13-1199.04","reason":"Plans for the worst case; calm under pressure."},{"code":"11-2033.00","reason":"Leads fundraising toward goals; persuasion and persistence."},{"code":"13-1131.00","reason":"Builds relationships toward a goal; resilience through no."},{"code":"43-1011.00","reason":"Leads a team day to day; dependable and organized."},{"code":"33-3051.00","reason":"Physical, disciplined, team-based work under pressure."}]');
